window.HB_TR["daniel"]["ur"]=["1۔ یہوحیقیم، بادشاہ یہوداہ کی حکومت کے تیسرے سال میں، بابل کا بادشاہ نبوکدنصر یروشلم آیا اور اس کا محاصرہ کر لیا۔\n2۔ اور خداوند نے یہوداہ کے بادشاہ یہویاکیم کو اپنے ہاتھ میں دیا، خدا کے گھر کے برتنوں کے کچھ حصے کے ساتھ، جنہیں اس نے شینار کی سرزمین میں اپنے خدا کے گھر لے جایا؛ اور اس نے برتن اپنے خدا کے خزانے میں لے آئے۔\n3۔ اور بادشاہ نے اپنے خواجہ سرا کے مالک اشپیناز سے کہا کہ وہ بنی اسرائیل، بادشاہ کی نسل اور شہزادوں کے بارے میں {یقین} لائے گا؛\n4۔ ایسے بچے جن میں کوئی داغ نہ ہو، لیکن وہ مہربان، حکمت میں ماہر، علم میں چالاک، سائنس کو سمجھنے والے ہوں، اور جن میں بادشاہ کے محل میں کھڑے ہونے کی صلاحیت ہو، اور جنہیں وہ کلدانیوں کی تعلیم اور زبان سکھا سکیں۔\n5۔ اور بادشاہ نے انہیں بادشاہ کے گوشت اور شراب کی روزانہ خوراک مقرر کی، تاکہ وہ تین سال تک کھلائیں تاکہ وہ بادشاہ کے سامنے کھڑے ہو سکیں۔ {شراب...: عبرانی۔ اس کے مشروب کی شراب}\n6۔ ان میں یہوداہ کی اولاد دانیال، حنانیہ، مشائل اور عزریاہ شامل تھے:\n7۔ جن کو خواجہ سراوں کے شہزادے نے نام دیے: کیونکہ اس نے دانیال کو بیلتیشزار کا نام دیا؛ اور حنانیا، شادرخ سے؛ اور مشائل، میشاخ سے؛ اور عزریہ، عبدنیگو سے۔\n8۔ لیکن دانیال نے دل ہی دل میں ارادہ کیا کہ وہ خود کو بادشاہ کے گوشت کے حصے یا اس شراب سے آلودہ نہ کرے جو وہ پیتا ہے: اس لیے اس نے خواجہ سرا کے شہزادے سے درخواست کی کہ وہ خود کو ناپاک نہ کرے۔\n9۔ اب خدا نے دانیال کو خواجاؤں کے شہزادے کے ساتھ مہربان اور محبت میں مبتلا کر دیا تھا۔\n10۔ اور خواجہ سرا کے شہزادے نے دانیال سے کہا، میں اپنے آقا بادشاہ سے ڈرتا ہوں، جس نے تمہارا گوشت اور مشروب مقرر کیا ہے: کیونکہ وہ تمہارے چہروں کو تمہارے جیسے بچوں سے زیادہ پسند کرنے والا کیوں دیکھے؟ پھر تم مجھے بادشاہ کے سامنے اپنا سر خطرے میں ڈالنے پر مجبور کرو گے۔ {اس سے بھی بدتر...: عبرانی۔ sadder} {sort: or, term, or, continuance?}\n11۔ پھر دانیال نے ملزار سے کہا، جسے خواجہ سرا کے شہزادے نے دانیال، حنانیا، مشائل اور عزریاہ پر مقرر کیا تھا، {میلزار: یا، سرپرست}\n12. اپنے بندوں کو ثابت کرو، میں تم سے درخواست کرتا ہوں، دس دن؛ اور وہ ہمیں کھانے کے لیے نبض اور پینے کے لیے پانی دیں۔ {نبض: ہیب۔ نبض کا ہے} {کھانے کے لیے...: عبرانی۔ تاکہ ہم کھا سکیں، وغیرہ}\n13۔ تو پھر ہمارے چہرے آپ کے سامنے دیکھیں، اور ان بچوں کے چہرے جو بادشاہ کے گوشت کے حصے سے کھاتے ہیں، اور جیسا آپ دیکھتے ہیں، اپنے خادموں کے ساتھ پیش آئیں۔\n14۔ اس لیے اس نے اس معاملے میں ان کی اجازت دی، اور انہیں دس دن ثابت کیا۔\n15۔ اور دس دن کے آخر میں ان کے چہرے ان تمام بچوں سے زیادہ خوبصورت اور موٹے نظر آئے جو بادشاہ کے گوشت کا حصہ کھاتے تھے۔\n16۔ یوں میلزار نے ان کے گوشت کا حصہ اور شراب چھین لی جو انہیں پینا تھا؛ اور انہیں نبض دی۔\n17۔ جہاں تک ان چار بچوں کا تعلق ہے، خدا نے انہیں علم اور حکمت میں علم اور مہارت دی: اور دانیال نے ہر خواب اور خواب میں سمجھ بوجھ حاصل کی۔ {ڈینیئل...: یا، اس نے ڈینیئل کو سمجھایا}\n18۔ اب جب بادشاہ نے کہا تھا کہ انہیں اندر لانا چاہیے، تو خواجہ سرا کے شہزادے نے انہیں نبوکدنضر کے سامنے لے آیا۔\n19۔ اور بادشاہ نے ان سے رابطہ کیا؛ اور ان سب میں دانیال، حنانیہ، مشائیل، اور عزریاہ جیسا کوئی نہیں ملا، اس لیے وہ بادشاہ کے سامنے کھڑے تھے۔\n20۔ اور حکمت اور سمجھ بوجھ کے تمام معاملات میں، جو بادشاہ نے ان سے پوچھا، وہ اپنے تمام جادوگروں اور نجومیوں سے دس گنا بہتر پایا جو اس کی پوری سلطنت میں تھے۔ {حکمت...: عبرانی۔ سمجھ بوجھ کی حکمت}\n21۔ اور دانیال بادشاہ سائرس کے پہلے سال تک جاری رہا۔","1۔ اور نبوکدنضر کی حکومت کے دوسرے سال میں نبوکدنضر نے خواب دیکھے، جن سے اس کی روح پریشان ہو گئی اور اس کی نیند اس سے ٹوٹ گئی۔\n2۔ پھر بادشاہ نے حکم دیا کہ جادوگروں، نجومیوں، جادوگروں، اور کلدانیوں کو بلایا جائے تاکہ بادشاہ کو اس کے خواب دکھائیں۔ تو وہ آئے اور بادشاہ کے سامنے کھڑے ہو گئے۔\n3۔ اور بادشاہ نے ان سے کہا، میں نے خواب دیکھا ہے، اور میرا دل اس خواب کو جان کر پریشان ہوا۔\n4۔ پھر کلدانیوں نے سریانی زبان میں بادشاہ سے کہا، اے بادشاہ، ہمیشہ زندہ رہو: اپنے بندوں کو خواب سناؤ، اور ہم اس کی تعبیر دکھائیں گے۔ {اے بادشاہ...: (چالڈی، باب سات کے آخر تک}\n5۔ بادشاہ نے جواب دیا اور کلدانیوں سے کہا، وہ چیز میرے پاس نہیں ہے: اگر تم مجھے خواب کی تعبیر کے ساتھ نہ بتاؤ گے، تو تم ٹکڑے ٹکڑے ہو جاؤ گے، اور تمہارے گھر گوبر کے ڈھیر بن جائیں گے۔ {کٹ...: چالڈی، بنے ٹکڑے}\n6۔ لیکن اگر تم خواب اور اس کی تعبیر دکھاؤ گے، تو تمہیں میرے طرف سے تحفے، انعامات اور عظیم عزت ملے گی: تو مجھے خواب اور اس کی تعبیر دکھاؤ۔ {انعامات: یا، فیس}\n7۔ انہوں نے دوبارہ جواب دیا اور کہا، بادشاہ اپنے خادموں کو خواب سنائے، اور ہم اس کی تعبیر دکھائیں گے۔\n8۔ بادشاہ نے جواب دیا اور کہا، میں یقین سے جانتا ہوں کہ تم وقت حاصل کرو گے، کیونکہ تم دیکھتے ہو کہ وہ چیز مجھ سے چلی گئی ہے۔ {gain: Chaldee, buy}\n9۔ لیکن اگر تم مجھے خواب نہیں بتانا چاہتے، تو تمہارے لیے صرف ایک حکم ہے: کیونکہ تم نے میرے سامنے جھوٹے اور بگڑے ہوئے الفاظ تیار کیے ہیں، جب تک وقت بدل نہ جائے: تو مجھے خواب سناؤ، اور میں جان جاؤں گا کہ تم مجھے اس کی تعبیر دکھا سکتے ہو۔\n10۔ کلدانیوں نے بادشاہ کے سامنے جواب دیا اور کہا، زمین پر کوئی انسان بادشاہ کا معاملہ نہیں دکھا سکتا: اس لیے کوئی بادشاہ، سردار یا حکمران نہیں جو کسی جادوگر، نجومی یا کلدانی سے یہ سوال کرے۔\n11۔ اور یہ ایک نایاب چیز ہے جس کی بادشاہ کو ضرورت ہے، اور کوئی اور بادشاہ کے سامنے یہ دکھا نہیں سکتا، سوائے دیوتاؤں کے، جن کی رہائش گوشت سے نہیں۔\n12۔ اسی وجہ سے بادشاہ غصے میں اور بہت غصے میں تھا، اور حکم دیا کہ بابل کے تمام دانا لوگوں کو ختم کر دیا جائے۔\n13۔ اور حکم جاری ہوا کہ عقلمندوں کو قتل کیا جائے؛ اور انہوں نے دانیال اور اس کے ساتھیوں کو مارنے کی کوشش کی۔\n14۔ پھر دانیال نے مشورے اور حکمت کے ساتھ آریوخ کو جواب دیا، جو بادشاہ کے محافظ کا کپتان تھا، جو بابل کے دانا {لوگ} کو قتل کرنے نکلا تھا: {جواب دیا...: کلدی، واپس آ گیا} {کپتان...: یا، چیف مارشل: کلدی، پھانسی دینے والوں کا سردار، یا، ذبح کرنے والا}\n15۔ اس نے جواب دیا اور بادشاہ کے کپتان آریوک سے کہا، بادشاہ کی طرف سے یہ حکم اتنی جلد بازی کیوں ہے؟ پھر آریوخ نے یہ بات ڈینیئل کو بتائی۔\n16۔ پھر دانیال اندر گیا، اور بادشاہ سے دعا کی کہ وہ اسے وقت دے، اور بادشاہ کو اس کی تشریح دکھائے۔\n17۔ پھر دانیال اپنے گھر گیا اور اس بات کو حنانیا، میشائل اور عزریا، جو اس کے ساتھیوں تھے، بتایا:\n18۔ کہ وہ اس راز کے بارے میں آسمان کے خدا کی رحمت چاہتے ہیں؛ کہ دانیال اور اس کے ساتھی بابل کے باقی دانا لوگوں کے ساتھ فنا نہ ہوں۔ {خدا کا: کالدی، خدا کے سامنے سے} {کہ ڈینیئل...: یا، کہ وہ دانیال کو تباہ نہ کریں، وغیرہ}\n19۔ پھر وہ راز دانیال کو رات کی نظر میں ظاہر ہوا۔ پھر دانیال نے آسمان کے خدا کو برکت دی۔\n20۔ دانیال نے جواب دیا اور کہا، خدا کا نام ہمیشہ ہمیشہ کے لیے مبارک ہو: کیونکہ حکمت اور طاقت اس کی ہے:\n21۔ اور وہ وقت اور موسم بدلتا ہے: بادشاہوں کو ہٹاتا ہے، بادشاہوں کو بٹھاتا ہے: وہ دانوں کو حکمت دیتا ہے، اور سمجھ بوجھ رکھنے والوں کو علم دیتا ہے:\n22۔ وہ گہری اور خفیہ باتیں ظاہر کرتا ہے: وہ جانتا ہے کہ اندھیرے میں کیا ہے، اور روشنی اس کے ساتھ رہتی ہے۔\n23. میں تیرا شکر ادا کرتا ہوں، اور تیرا شکر ادا کرتا ہوں، اے میرے باپ و اجداد کے خدا، جس نے مجھے حکمت اور طاقت دی، اور اب مجھے وہ سب بتا دیا جو ہم تم سے چاہتے تھے: کیونکہ تو نے ہمیں بادشاہ کا معاملہ بتا دیا ہے۔\n24۔ لہٰذا دانیال آریوخ کے پاس گیا، جسے بادشاہ نے بابل کے دانا لوگوں کو تباہ کرنے کا حکم دیا تھا: وہ گیا اور اسے یہ کہا؛ بابل کے عقلمندوں کو تباہ نہ کرو: مجھے بادشاہ کے سامنے لے آؤ، اور میں بادشاہ کو اس کی تشریح دکھاؤں گا۔\n25۔ پھر اریوخ نے جلدی میں دانیال کو بادشاہ کے سامنے بلایا اور اسے کہا، میں نے یہوداہ کے قیدیوں میں سے ایک آدمی کو پایا ہے جو بادشاہ کو اس تشریح سے آگاہ کرے گا۔ {میرے پاس...: چالڈی، یہ میں نے پایا ہے} {قیدی...: کلدی، یہوداہ کی قید کے بچے}\n26۔ بادشاہ نے جواب دیا اور دانیال سے کہا، جس کا نام {تھا} بیلتیشاصر، کیا تم مجھے وہ خواب اور اس کی تعبیر بتا سکتے ہو؟\n27۔ دانیال نے بادشاہ کی موجودگی میں جواب دیا اور کہا، وہ راز جو بادشاہ نے مانگا ہے، وہ عقلمندوں، نجومیوں، جادوگروں، اور پیش گو بادشاہ کو نہیں بتا سکتے؛\n28۔ لیکن آسمان میں ایک خدا ہے جو راز ظاہر کرتا ہے، اور بادشاہ نبوکدنضر کو بتاتا ہے کہ آخری دنوں میں کیا ہوگا۔ تمہارا خواب، اور تمہارے بستر پر سر کے خواب، یہ ہیں؛ {بناتا ہے...: چالڈی، نے ظاہر کر دیا ہے}\n29. جہاں تک تمہارا تعلق ہے، اے بادشاہ، تمہارے خیالات تمہارے بستر پر آئے، جو بعد میں ہونا چاہیے: اور جو راز ظاہر کرتا ہے وہ تمہیں بتاتا ہے کہ کیا ہونے والا ہے۔ {آیا: کلدی، اوپر آیا}\n30۔ لیکن جہاں تک میرا تعلق ہے، یہ راز مجھے کسی بھی حکمت کی وجہ سے ظاہر نہیں کیا گیا جو میرے پاس کسی بھی زندہ سے زیادہ ہے، بلکہ ان کے لیے ہے تاکہ بادشاہ کو تشریح معلوم ہو، اور تاکہ تم اپنے دل کے خیالات جان سکو۔ {مگر اس کے لیے...: یا، اگر اس نیت سے کہ تشریح بادشاہ کو معلوم ہو}\n31۔ اے بادشاہ، تو دیکھو، اور ایک عظیم تصویر دیکھو۔ یہ عظیم شبیہ، جس کی روشنی {لاجواب} تھی، آپ کے سامنے کھڑی تھی؛ اور اس کی شکل بہت خراب تھی۔ {ساوسٹ: چالڈی، دیکھنا ضائع نہیں}\n32۔ اس مجسمے کا سر {نفیس سونے کا} تھا، اس کا سینہ اور بازو چاندی کے تھے، اس کا پیٹ اور رانیں پیتل کی تھیں، {رانیں: یا پہلو}\n33۔ اس کی ٹانگیں لوہے کے، اس کے پاؤں کچھ لوہے کے اور کچھ مٹی کے۔\n34۔ تم نے دیکھا یہاں تک کہ ایک پتھر بغیر ہاتھوں کے کاٹ دیا گیا، جس نے اس کے قدموں پر لوہے اور مٹی کے مجسمے کو مارا اور انہیں ٹکڑے ٹکڑے کر دیا۔ {بغیر...: یا، جو ہاتھ میں نہیں تھا}\n35۔ پھر لوہا، مٹی، پیتل، چاندی اور سونا ٹکڑوں میں ٹوٹ گئے، اور گرمیوں کے تھریشنگ فلورز کے بھوسے کی طرح بن گئے؛ اور ہوا انہیں لے گئی، یہاں تک کہ ان کے لیے کوئی جگہ نہ ملی: اور وہ پتھر جو اس تصویر کو مارا تھا، ایک عظیم پہاڑ بن گیا، اور پوری زمین کو بھر دیا۔\n36. یہ {ہے} خواب؛ اور ہم اس کی تشریح بادشاہ کے سامنے سنائیں گے۔\n37۔ اے بادشاہ، تو بادشاہوں کا بادشاہ ہو: کیونکہ آسمان کے خدا نے تمہیں بادشاہت، طاقت، طاقت اور جلال دیا ہے۔\n38۔ اور جہاں بھی انسان کے بچے رہتے ہیں، اس نے میدان کے جانور اور آسمان کے پرندوں کو تمہارے ہاتھ میں دے دیا ہے، اور تمہیں ان سب پر حکمران بنا دیا ہے۔ تم یہ سونے کا سر ہو۔\n39۔ اور تمہارے بعد ایک اور بادشاہت جنم لے گی جو تم سے کمتر ہو، اور ایک تیسری پیتل کی بادشاہت جو پوری زمین پر حکمرانی کرے گی۔\n40۔ اور چوتھی بادشاہی لوہے کی طرح مضبوط ہوگی: جیسے لوہا ٹکڑوں میں ٹوٹ کر سب کو زیر کر دے گا؛ اور جیسے لوہا جو ان سب کو توڑے گا، وہ ٹکڑوں میں ٹوٹے گا اور زخمی ہو جائے گا۔\n41۔ اور جب تم نے برتن بنانے والوں کی مٹی کے کچھ حصے اور لوہے کے پاؤں اور انگلیاں دیکھی ہیں، تو بادشاہی تقسیم ہو جائے گی؛ لیکن اس میں لوہے کی مضبوطی ہوگی، کیونکہ تم نے دیکھا کہ لوہے کو کیچڑ میں مٹی ملا ہوا ہے۔\n42. اور جیسے پاؤں کی انگلیاں لوہے کے حصے اور مٹی کے حصے تھے، ویسے ہی بادشاہت جزوی طور پر مضبوط اور جزوی طور پر ٹوٹی ہوئی ہوگی۔ {ٹوٹا ہوا: یا، نازک}\n43۔ اور جہاں تم نے دیکھا کہ لوہا کیچڑی مٹی کے ساتھ ملا ہوا ہے، وہ انسانوں کے بیج میں گھل مل جائیں گے: لیکن وہ ایک دوسرے سے نہیں چمٹیں گے، جیسے لوہا مٹی کے ساتھ نہیں ملاتا۔ {ایک...: چالڈی، یہ اس کے ساتھ}\n44۔ اور ان بادشاہوں کے زمانے میں آسمان کا خدا ایک ایسی بادشاہت قائم کرے گا جو کبھی تباہ نہیں ہوگی: اور بادشاہی دوسروں کے لیے نہیں چھوڑے گی، {لیکن} یہ ٹکڑوں میں ٹوٹ جائے گی اور ان تمام سلطنتوں کو نگل جائے گی، اور ہمیشہ قائم رہے گی۔ {دن: کالدی، ان کے دن} {بادشاہت: چالڈی، اس کی بادشاہت}\n45۔ چونکہ تم نے دیکھا کہ پتھر پہاڑ سے بغیر ہاتھوں کے کاٹا گیا تھا، اور اس نے لوہا، پیتل، مٹی، چاندی اور سونا ٹکڑوں میں توڑ دیا؛ عظیم خدا نے بادشاہ کو وہ سب کچھ بتا دیا ہے جو بعد میں ہونے والا ہے: اور خواب یقینی ہے، اور اس کی تعبیر یقینی ہے۔ {بغیر...: یا، جو ہاتھ میں نہیں تھا} {آئندہ: چالڈی، اس کے بعد}\n46۔ پھر بادشاہ نبوکدنصر اس کے چہرے پر گر پڑا، دانیال کی عبادت کی، اور حکم دیا کہ وہ اسے قربان اور میٹھا خوشبو پیش کریں۔\n47۔ بادشاہ نے دانیال کو جواب دیا اور کہا، ایک سچائی کے بارے میں کہ تمہارا خدا دیوتاؤں کا خدا ہے، بادشاہوں کا رب ہے، اور رازوں کا انکشاف کرنے والا ہے، کیونکہ تم اس راز کو ظاہر کر سکتے ہو۔\n48۔ پھر بادشاہ نے دانیال کو عظیم آدمی بنایا، اسے کئی عظیم تحفے دیے، اور اسے بابل کے پورے صوبے کا حکمران مقرر کیا، اور بابل کے تمام عقلمندوں کے گورنروں کا سربراہ بنایا۔\n49۔ پھر دانیال نے بادشاہ سے درخواست کی، اور اس نے شادرخ، مشک اور عابدنیگو کو بابل کے صوبے کے معاملات پر مقرر کیا: لیکن دانیال بادشاہ کے دروازے پر بیٹھ گیا۔","1۔ نبوکدنصر بادشاہ نے سونے کی ایک تصویر بنائی، جس کی اونچائی {ساڑھ} کیوبٹ تھی، {اور} اس کی چوڑائی چھ ہوتیں: اس نے اسے بابل کے صوبے کے میدان دورا میں نصب کیا۔\n2۔ پھر بادشاہ نبوکدنصر نے شہزادوں، گورنرز، کپتانوں، ججوں، خزانے داروں، مشیروں، شیرفوں اور صوبوں کے تمام حکمرانوں کو جمع کرنے کے لیے بھیجا تاکہ بادشاہ نبوکدنصر کی بنائی گئی تصویر کی تقریب کے لیے آئیں۔\n3۔ پھر شہزادے، گورنر، اور کپتان، جج، خزانے دار، مشیر، شیرف اور صوبوں کے تمام حکمران اکٹھے ہوئے تاکہ بادشاہ نبوکدنضر کی بنائی گئی تصویر کی وقف کی جا سکے؛ اور وہ اس تصویر کے سامنے کھڑے ہو گئے جو نبوکدنضر نے بنائی تھی۔\n4۔ پھر ایک پیغامبر نے زور سے پکارا، اے لوگوں، قوموں اور زبانوں کو حکم دیا گیا ہے، {بلند آواز میں: کلدی، طاقت کے ساتھ} {یہ...: کلدی، وہ حکم دیتے ہیں}\n5. {وہ} جب آپ کارنیٹ، بانسری، ہارپ، سیک بٹ، زبور، ڈلسیمر اور ہر قسم کی موسیقی کی آواز سنتے ہیں، تو آپ گر کر اس سنہری تصویر کی عبادت کرتے ہیں جو نبوکدنضر بادشاہ نے بنائی ہے: {ڈلسیمر: یا، گاتے ہوئے: کلدی، سمفنی}\n6۔ اور جو گر کر عبادت نہیں کرے گا، اسی وقت اسے جلتی ہوئی آگ کی بھٹی میں پھینک دیا جائے گا۔\n7۔ اسی لیے، جب سب نے کارنیٹ، بانسر، ہارپ، سیک بٹ، زبور اور ہر قسم کی موسیقی کی آواز سنی، تو تمام لوگ، قومیں اور زبانیں گر گئیں اور اس سنہری تصویر کی عبادت کرنے لگے جو بادشاہ نبوکدنضر نے بنائی تھی۔\n8۔ اسی وقت کچھ کلدانی قریب آئے اور یہودیوں پر الزام لگایا۔\n9۔ انہوں نے بادشاہ نبوکدنضر سے کہا، اے بادشاہ، ہمیشہ زندہ رہو۔\n10۔ اے بادشاہ، تو نے حکم دیا ہے کہ ہر وہ شخص جو کارنیٹ، بانسی، ہارپ، سیک بٹ، زبور، اور ہر قسم کی موسیقی کی آواز سنے گا، وہ گر کر سنہری تصویر کی عبادت کرے گا: {ڈلسیمر: یا، گانا: چالڈی، سمفنی}\n11۔ اور جو گر کر پیتھ کی عبادت نہیں کرتا، {تاکہ} اسے جلتی ہوئی بھٹی کے بیچ میں پھینک دیا جائے۔\n12۔ کچھ یہودی ہیں جنہیں تم نے بابل کے صوبے، شادرخ، مشاخ، اور عبیدنیگو کے معاملات پر مقرر کیا ہے؛ یہ لوگ، اے بادشاہ، نے تمہیں نہیں دیکھا: وہ تیرے دیوتاؤں کی عبادت نہیں کرتے، نہ ہی اس سنہری تصویر کی عبادت کرتے ہیں جو تم نے بنائی ہے۔ {کیا ہے...: چالڈی، میں نے تم پر کوئی پرواہ نہیں کی}\n13۔ پھر نبوکدنضر نے {اپنی} غصے اور غصے میں حکم دیا کہ شادرخ، میشاک اور عبدنیگو کو لے آئے۔ پھر انہوں نے ان مردوں کو بادشاہ کے سامنے پیش کیا۔\n14۔ نبوکدنصر نے ان سے کہا، {کیا یہ سچ ہے}، اے شادرخ، میشاخ اور عبدنیگو، کیا تم میرے دیوتاؤں کی عبادت نہیں کرتے، نہ ہی اس سنہری تصویر کی عبادت کرتے ہو جو میں نے بنائی ہے؟ {صحیح: یا، مقصد کا}\n15۔ اب اگر تم تیار ہو کہ جب تم کارنیٹ، بانسر، ہارپ، سیک بٹ، زبور، اور ہر قسم کی موسیقی کی آواز سنو گے، تو تم گر کر اس تصویر کی عبادت کرو جو میں نے بنائی ہے؛ {خیر}: لیکن اگر تم عبادت نہیں کرو گے، تو اسی وقت تم جلتی ہوئی بھٹی کے بیچ میں پھینک دیے جاؤ گے؛ اور وہ خدا کون ہے جو تمہیں میرے ہاتھوں سے آزاد کرے گا؟ {ڈلسیمر: یا، گانا: چالڈی، سمفنی}\n16۔ شادرخ، مشاح اور عابدنیگو نے بادشاہ سے کہا، اے نبوکدنضر، ہم اس معاملے میں تمہیں جواب دینے میں محتاط نہیں ہیں۔\n17۔ اگر ایسا ہوا، تو ہمارا خدا جس کی ہم عبادت کرتے ہیں، ہمیں جلتی ہوئی بھٹی سے بچا سکتا ہے، اور وہ ہمیں تیرے ہاتھ سے آزاد کرے گا، اے بادشاہ۔\n18۔ لیکن اگر نہیں، تو تمہیں معلوم ہو، اے بادشاہ، کہ ہم تمہارے دیوتاؤں کی عبادت نہیں کریں گے، نہ ہی اس سنہری تصویر کی عبادت کریں گے جو تم نے بنائی ہے۔\n19۔ پھر نبوکدنصر غصے سے بھر گیا، اور اس کا چہرہ شادرخ، مشاخ، اور عبیدنیگو کے خلاف بدل گیا: {لہٰذا} اس نے کہا اور حکم دیا کہ وہ بھٹی کو اس سے سات گنا زیادہ گرم کریں جتنا وہ معمول کے مطابق گرم ہوتی تھی۔ {مکمل: چالڈی، بھرا ہوا}\n20۔ اور اس نے اپنی فوج میں موجود سب سے طاقتور سپاہیوں کو حکم دیا کہ وہ شادرخ، مشک اور عابدنیگو کو باندھیں، {اور} انہیں جلتی ہوئی آگ کی بھٹی میں پھینک دیں۔ {زیادہ تر...: چالڈی، طاقتور طاقت}\n21۔ پھر ان مردوں کو ان کے کوٹ، ہوسن، ٹوپیاں، اور دیگر کپڑوں میں باندھ دیا گیا اور جلتی ہوئی آگ کی بھٹی میں پھینک دیا گیا۔ {کوٹس: یا، مینٹلز} {ٹوپیاں: یا، پگڑیاں}\n22۔ لہٰذا چونکہ بادشاہ کا حکم فوری تھا اور بھٹی بہت زیادہ گرم تھی، آگ کی آگ نے ان مردوں کو مار ڈالا جنہوں نے شادرخ، مشک اور عبدنیگو کو سنبھالا۔ {حکم: کلدی، ورڈ} {شعلہ: یا، چنگاری}\n23۔ اور یہ تینوں آدمی، شادرخ، مشاخ، اور عبدنیگو، جلتی ہوئی آگ کی بھٹی کے بیچ میں بندھے ہوئے گر گئے۔\n24۔ پھر نبوکدنصر بادشاہ حیران رہ گیا، جلدی سے اٹھا، {اور} اپنے مشیروں سے کہا، کیا ہم نے تین آدمیوں کو آگ کے بیچ میں باندھ کر نہیں پھینک دیا؟ انہوں نے جواب دیا اور بادشاہ سے کہا، سچ ہے، اے بادشاہ۔ {مشیر: یا، گورنرز}\n25۔ اس نے جواب دیا اور کہا، دیکھو، میں چار آدمیوں کو آگ کے بیچ چلتے ہوئے دیکھتا ہوں، اور انہیں کوئی چوٹ نہیں؛ اور چوتھے کی صورت خدا کے بیٹے کی طرح ہے۔ {وہ...: چالڈی، ان میں کوئی تکلیف نہیں}\n26۔ پھر نبوکدنضر جلتی ہوئی بھٹی کے دہانے کے قریب آیا، {اور} بولا، اور کہا، شادرخ، مشک اور عبدنیگو، اے اعلیٰ خدا کے بندے، باہر آؤ، اور یہاں آؤ۔ پھر شادرخ، مشک اور عابدنیگو آگ کے بیچ سے باہر آئے۔ {منہ: چالڈی، دروازہ}\n27۔ اور شہزادے، گورنر، کپتان، اور بادشاہ کے مشیر، جو اکٹھے ہوئے تھے، نے ان مردوں کو دیکھا، جن کے جسموں پر آگ کا کوئی اثر نہیں تھا، نہ ان کے سر کا ایک بال جل گیا تھا، نہ ان کے کوٹ بدلے گئے تھے، نہ آگ کی بو ان پر منتقل ہوئی تھی۔\n28۔ {پھر} نبوکدنضر نے کہا اور کہا، مبارک ہو شدرخ، مشاخ اور عبدنیگو کے خدا کو، جس نے اپنا فرشتہ بھیجا، اور اپنے بندوں کو نجات دی جو اس پر بھروسہ کرتے تھے، بادشاہ کے کلام کو بدل دیا اور اپنے جسم قربان کر دیے، تاکہ وہ کسی خدا کی عبادت نہ کر سکیں، سوائے اپنے خدا کے۔\n29۔ لہٰذا میں ایک فرمان دیتا ہوں کہ ہر قوم، قوم اور زبان جو شادرخ، مشک اور عابدنیگو کے خدا کے خلاف کوئی غلط بات کرے گی، اسے ٹکڑوں میں کاٹ دیا جائے گا، اور ان کے گھروں کو گوبر کے ڈھیر میں تبدیل کیا جائے گا: کیونکہ اس کے بعد کوئی اور خدا نجات نہیں دے سکتا۔ {میں کہتا ہوں...: چالدی، ایک فرمان میرے ذریعے جاری کیا گیا ہے} {کوئی بھی...: چالڈی، غلطی} {کٹ...: چالڈی، بنے ٹکڑے}\n30۔ پھر بادشاہ نے شادرخ، مشک اور عبدنیگو کو بابل کے صوبے میں ترقی دی۔ {ترقی: چالڈی، خوشحالی کے لیے بنایا گیا}","1۔ نبوکدنصر بادشاہ، تمام لوگوں، قوموں، اور زبانوں کے لیے، جو زمین پر بستے ہیں؛ آپ پر سلامتی ملے۔\n2. میں نے اچھا سمجھا کہ میں وہ نشانیاں اور عجائبات دکھاؤں جو اعلیٰ خدا نے میرے لیے کیے ہیں۔ {میں نے سوچا...: چالڈی، یہ میرے سامنے مناسب تھا}\n3. اس کے نشانات کتنے عظیم ہیں! اور اس کے عجائبات کتنے عظیم ہیں! اس کی سلطنت ایک دائمی بادشاہت ہے، اور اس کی حکمرانی نسل در نسل ہے۔\n4۔ میں نبوکدنصر میرے گھر میں آرام کر رہا تھا، اور اپنے محل میں خوشحال تھا:\n5۔ میں نے ایک خواب دیکھا جس نے مجھے خوفزدہ کر دیا، اور میرے بستر پر خیالات اور میرے ذہن کے مناظر مجھے پریشان کر رہے تھے۔\n6۔ اسی لیے میں نے حکم دیا کہ بابل کے تمام دانا لوگوں کو اپنے سامنے لاؤں تاکہ وہ مجھے خواب کی تعبیر بتا سکیں۔\n7۔ پھر جادوگر، نجومی، کلدانی اور غیب گو آئے: اور میں نے ان کے سامنے خواب سنایا؛ لیکن انہوں نے مجھے اس کی تشریح سے آگاہ نہیں کیا۔\n8۔ لیکن آخر میں دانیال میرے سامنے آیا، جس کا نام {تھا} بیلتیشزار تھا، میرے خدا کے نام کے مطابق، اور جس میں مقدس دیوتاؤں کی روح ہے: اور اس کے سامنے میں نے خواب سنایا اور {کہا},\n9۔ اے بیلتیشزار، جادوگروں کے استاد، کیونکہ میں جانتا ہوں کہ مقدس دیوتاؤں کی روح تمہارے اندر ہے، اور کوئی راز تمہیں پریشان نہیں کرتا، تو مجھے وہ خواب بتاؤ جو میں نے دیکھے ہیں، اور ان کی تعبیر بھی۔\n10. یوں میرے بستر میں سر کے خواب تھے؛ میں نے زمین کے بیچ میں ایک درخت دیکھا، اور اس کی اونچائی بہت زیادہ تھی۔ {میں نے دیکھا: چالڈی، میں دیکھ رہا تھا}\n11۔ درخت بڑھا، مضبوط ہوا، اور اس کی اونچائی آسمان تک پہنچ گئی، اور اس کا نظارہ زمین کے آخر تک پہنچ گیا:\n12۔ اس کے پتے خوبصورت تھے، اور اس کے پھل بہت تھے، اور اس میں سب کے لیے گوشت تھا: کھیت کے جانوروں کے نیچے سایہ تھا، اور آسمان کے پرندے اس کی شاخوں میں رہتے تھے، اور ہر گوشت کو اس سے کھلایا جاتا تھا۔\n13۔ میں نے اپنے بستر پر اپنے سر کے خوابوں میں دیکھا، اور دیکھتے ہی آسمان سے ایک محافظ اور ایک مقدس شخص نیچے آیا؛\n14۔ اس نے بلند آواز میں پکارا اور کہا، درخت کو کاٹ دو، اس کی شاخیں کاٹ دو، اس کے پتے جھاڑ دو، اور اس کے پھل بکھیر دو: جانور اس کے نیچے سے بھاگ جائیں، اور پرندوں کو اس کی شاخوں سے: {بلند آواز میں: کلدی، طاقت سے}\n15۔ پھر بھی اپنی جڑوں کے ٹھونٹھ کو زمین میں چھوڑ دے، چاہے لوہے اور پیتل کی پٹی کے ساتھ بھی، کھیت کی نرم گھاس میں؛ اور اسے آسمان کی شبنم سے بھیگ جائے، اور اس کا حصہ زمین کی گھاس میں موجود جانوروں کے ساتھ ہو:\n16۔ اس کا دل انسان کے دل سے بدل جائے، اور جانور کا دل اسے دیا جائے؛ اور سات بار اس پر گزر گیا۔\n17۔ یہ معاملہ نگہبانوں کے حکم اور مقدس لوگوں کے حکم کے تحت ہے: اس نیت سے کہ زندہ جان سکے کہ سب سے اعلیٰ انسانوں کی بادشاہی میں حکمرانی کرتا ہے، اور اسے جسے چاہے دیتا ہے، اور اس پر سب سے نچلے آدمی کو بٹھاتا ہے۔\n18۔ یہ خواب میں نے بادشاہ نبوکدنصر دیکھا ہے۔ اب تو، اے بیلتیشزار، اس کی تشریح بیان کرو، کیونکہ میرے سلطنت کے تمام دانا مجھے اس تشریح کو بتا نہیں سکتے: لیکن تو قابل ہو؛ کیونکہ مقدس دیوتاؤں کی روح تمہارے اندر ہے۔\n19۔ پھر دانیال، جس کا نام {تھا} بیلٹیشزار تھا، ایک گھنٹے کے لیے حیران رہ گیا، اور اس کے خیالات نے اسے پریشان کر دیا۔ بادشاہ نے کہا، بیلتیشاصر، خواب یا اس کی تعبیر تمہیں پریشان نہ کرے۔ بیلتیشزار نے جواب دیا اور کہا، میرے رب، یہ خواب ان لوگوں کے لیے ہو جو تم سے نفرت کرتے ہیں، اور اس کی تعبیر تمہارے دشمنوں کے لیے بھی۔\n20۔ وہ درخت جسے تم نے دیکھا، جو بڑھا اور مضبوط تھا، جس کی اونچائی آسمان تک پہنچی، اور اس کی نظر پوری زمین تک؛\n21۔ جس کے پتے {خوب} تھے، اور ان کے پھل بہت تھے، اور اس میں سب کے لیے گوشت تھا؛ جس کے نیچے میدان کے جانور رہتے تھے، اور جن کی شاخوں پر آسمان کے پرندے رہتے تھے:\n22. اے بادشاہ، تو ہی ہو جو بڑا ہو کر مضبوط ہوتا ہے: کیونکہ تیری عظمت بڑھتی ہے، آسمان تک پہنچتی ہے، اور تیری سلطنت زمین کے آخر تک پہنچتی ہے۔\n23۔ اور جب بادشاہ نے دیکھا کہ ایک نگہبان اور ایک مقدس آسمان سے اتر رہے ہیں اور کہہ رہے ہیں، درخت کو کاٹ کر تباہ کر دو؛ پھر بھی اس کی جڑوں کے ٹھونٹھ کو زمین میں چھوڑ دو، چاہے لوہے اور پیتل کی پٹی کے ساتھ بھی، کھیت کی نرم گھاس میں؛ اور اسے آسمان کی اوس سے بھیگ جائے، اور اس کا حصہ کھیت کے جانوروں کے ساتھ رہے، جب تک کہ سات بار اس پر نہ گزر جائے؛\n24. یہ {ہے} تشریح، اے بادشاہ، اور یہ {ہے} سب سے بلند کا حکم ہے، جو میرے رب بادشاہ پر آیا ہے:\n25۔ کہ وہ تمہیں انسانوں سے نکالیں گے، اور تمہارا مسکن کھیت کے جانوروں کے ساتھ ہوگا، اور وہ تمہیں گھاس کھلانے پر مجبور کریں گے، اور وہ تمہیں آسمان کی اوس سے گیلا کریں گے، اور سات بار تم پر گزریں گے، جب تک تم جان لو کہ سب سے اعلیٰ انسانوں کی بادشاہی میں حکمرانی کرتا ہے،  اور جسے چاہے دے گا۔\n26. اور جہاں انہوں نے حکم دیا کہ درخت کی جڑوں کے تنے کو چھوڑ دیا جائے؛ تمہاری بادشاہی تمہارے لیے یقینی ہوگی، جب تم جان لو گے کہ آسمان حکمرانی کرتے ہیں۔\n27۔ لہٰذا، اے بادشاہ، میری نصیحت تمہیں قبول کر، اور اپنے گناہوں کو راستبازی سے توڑ، اور اپنے گناہوں کو غریبوں پر رحم کر کے توڑو؛ اگر یہ تمہاری سکون کی لمبائی ہو۔ {ایک لمبائی...: یا، تمہاری غلطی کا شفا}\n28۔ یہ سب بادشاہ نبوکدنضر پر ہوا۔\n29۔ بارہ ماہ کے بعد وہ بابل کی بادشاہت کے محل میں چلا۔ {اندر: یا، اوپر}\n30۔ بادشاہ نے کہا اور کہا، کیا یہ عظیم بابل نہیں ہے، جو میں نے اپنی طاقت اور اپنی عظمت کے لیے بادشاہت کے گھر کے لیے بنایا ہے؟\n31۔ جب لفظ {تھا} بادشاہ کے منہ میں تھا، آسمان سے ایک آواز آئی، {کہتی ہے}، اے بادشاہ نبوکدنضر، یہ آپ سے کہا گیا ہے؛ بادشاہی تم سے جدا ہو گئی ہے۔\n32۔ اور وہ تمہیں انسانوں سے نکال دیں گے، اور تمہارا گھر کھیت کے جانوروں کے ساتھ ہوگا، وہ تمہیں گھاس کھلائیں گے جیسے بیل، اور سات بار تم پر سے گزریں گے، یہاں تک کہ تم جان لو کہ سب سے اعلیٰ انسانوں کی بادشاہی میں حکمرانی کرتا ہے، اور جسے چاہے دیتا ہے۔\n33۔ وہی وقت نبوکدنصر پر پورا ہوا: اور اسے انسانوں سے دور کر دیا گیا، اس نے گھاس کو بیلوں کی طرح کھایا، اور اس کا جسم آسمان کی شبنم سے بھیگ گیا، یہاں تک کہ اس کے بال عقاب کے پر کی طرح اگ گئے، اور ناخن پرندوں کے پنجوں کی طرح نکل آئے۔\n34۔ اور آخر میں میں نے نبوکدنضر نے اپنی آنکھیں آسمان کی طرف اٹھائیں، اور میری سمجھ مجھے واپس آئی، اور میں نے سب سے بلند کو برکت دی، اور اس کی تعریف اور عزت دی جو ہمیشہ زندہ ہے، جس کی حکمرانی دائمی حکمرانی ہے، اور اس کی بادشاہی نسل در نسل جاری رہتی ہے:\n35۔ اور زمین کے تمام باشندے کچھ بھی نہیں سمجھے جاتے ہیں: اور وہ اپنی مرضی کے مطابق آسمان کی فوج میں اور زمین کے باشندوں میں کام کرتا ہے: اور کوئی اس کا ہاتھ روک نہیں سکتا، یا اسے نہیں کہہ سکتا، تم کیا کرتے ہو؟\n36۔ اسی وقت میری عقل واپس آ گئی؛ اور میری بادشاہی کی شان کے لیے، میری عزت اور روشنی مجھے واپس آئی؛ اور میرے مشیروں اور لارڈز نے مجھ سے رابطہ کیا؛ اور میں اپنی سلطنت میں مستحکم ہو گیا، اور مجھ میں اعلیٰ عظمت شامل کی گئی۔\n37۔ اب میں نبوکدنصر آسمان کے بادشاہ کی تعریف، تعریف اور عزت کرتا ہوں، جن کے اعمال سچائی اور اس کے طریقے ہیں، اور جو غرور میں چلتے ہیں وہ ذلیل کر سکتا ہے۔","1۔ بادشاہ بلشصر نے اپنے ہزاروں سرداروں کے لیے ایک عظیم دعوت منائی، اور ہزاروں کے سامنے شراب پی۔\n2۔ بلشصر، جب وہ شراب چکھ رہا تھا، حکم دیا کہ وہ سونے اور چاندی کے برتن لے آئے جو اس کے والد نبوکدنصر نے یروشلم میں واقع مندر سے نکالے تھے؛ تاکہ بادشاہ، اس کے شہزادے، اس کی بیویاں اور اس کی کنیزیں اس میں پی سکیں۔ {والد: یا، دادا} {لیا گیا: چالڈی، لایا گیا}\n3۔ پھر وہ سونے کے برتن لے آئے جو خدا کے گھر کے مندر سے نکالے گئے تھے جو یروشلم میں تھا؛ اور بادشاہ، اس کے شہزادے، اس کی بیویاں، اور اس کی کنیزیں ان میں پیتی تھیں۔\n4۔ وہ شراب پیتے، اور سونے، چاندی، پیتل، لوہے، لکڑی اور پتھر کے دیوتاؤں کی تعریف کرتے۔\n5۔ اسی گھنٹے میں ایک آدمی کے ہاتھ کی انگلیاں نکلیں، اور بادشاہ کے محل کی دیوار کی چوٹی پر شمعدانی کے اسٹک پر لکھا: اور بادشاہ نے اس ہاتھ کا وہ حصہ دیکھا جس پر لکھا تھا۔\n6۔ پھر بادشاہ کا چہرہ بدل گیا، اور اس کے خیالات اسے پریشان کرنے لگے، یہاں تک کہ اس کی کمر کے جوڑ ڈھیلے ہو گئے، اور اس کے گھٹنے ایک دوسرے سے ٹکرا گئے۔ {چہرہ: چالڈی، روشنیاں} {تبدیل کیا گیا: چالڈی، بدل دیا} {جوڑ: اور، گرڈلز: چالڈی، بائنڈنگز، یا، گانٹھیں}\n7۔ بادشاہ نے بلند آواز میں پکارا کہ نجومیوں، کلدانی اور پیش گوؤں کو بلائے۔ {اور} بادشاہ نے بابل کے دانا لوگوں سے کہا، جو بھی یہ تحریر پڑھے گا اور مجھے اس کی تشریح دکھائے گا، وہ سرخ لباس میں ملبوس ہوگا، اور اس کے گلے میں سونے کی زنجیر ہوگی، اور وہ سلطنت کا تیسرا حکمران ہوگا۔ {بلند آواز میں: چالڈی، طاقت کے ساتھ} {اسکارلٹ: یا، جامنی}\n8۔ پھر بادشاہ کے تمام دانا آئے: لیکن وہ تحریر پڑھ نہیں سکتے تھے اور نہ ہی بادشاہ کو اس کی تشریح بتا سکتے تھے۔\n9۔ پھر بادشاہ بلشزار بہت پریشان ہوا، اس کا چہرہ بدل گیا، اور اس کے سردار حیران رہ گئے۔ {چہرہ: چالڈی، روشنیاں}\n10۔ {اب} ملکہ، بادشاہ اور اس کے لارڈز کے الفاظ کی وجہ سے، ضیافت کے گھر میں آئیں: {اور} ملکہ نے کہا اور کہا، اے بادشاہ، ہمیشہ زندہ رہو: اپنے خیالات تمہیں پریشان نہ کریں، نہ تمہارا چہرہ بدلنے دو:\n11۔ تیری بادشاہی میں ایک انسان ہے، جس میں مقدس دیوتاؤں کی روح ہے؛ اور تمہارے باپ کے زمانے میں روشنی، سمجھ اور حکمت، دیوتاؤں کی حکمت کی طرح، اس میں پائی گئی؛ جسے بادشاہ نبوکدنصر نے تمہارے والد بادشاہ، {میں کہتا ہوں}، تمہارا والد، جادوگروں، نجومیوں، کلدانیوں اور فالگوؤں کا مالک بنایا؛ {والد: یا، دادا}\n12. چونکہ ایک عمدہ روح، علم، اور سمجھ، خوابوں کی تعبیر، سخت جملے سنانا، اور شکوک و شبہات دور کرنا، اسی دانیال میں پائے گئے، جسے بادشاہ نے بیلتیشزار کا نام دیا: اب دانیال کو بلایا جائے، اور وہ تعبیر دکھائے گا۔ {ترجمہ: یا، ایک مترجم کا} {تحلیل ہونا: یا، تحلیل کرنے والے کا} {شک: چالڈی، گرہیں}\n13۔ پھر دانیال کو بادشاہ کے سامنے پیش کیا گیا۔ {اور} بادشاہ نے دانیال سے کہا، {کیا تو} وہ دانیال ہے، جو یہوداہ کی قید کے بچوں میں سے ہے، جسے میرے والد نے یہودیوں سے نکالا تھا؟ {والد: یا، دادا}\n14. میں نے تمہارے بارے میں بھی سنا ہے کہ دیوتاؤں کی روح {تمہاری} میں ہے، اور {کہ} روشنی، سمجھ اور بہترین حکمت تم میں پائی جاتی ہے۔\n15۔ اور اب دانا {لوگ}، نجومی، میرے سامنے آئے ہیں تاکہ وہ یہ تحریر پڑھیں اور اس کی تشریح مجھے بتائیں: لیکن وہ اس چیز کی تشریح ظاہر نہ کر سکے:\n16۔ اور میں نے تمہارے بارے میں سنا ہے کہ تم تشریحات کر سکتے ہو، اور شک و شبہات دور کر سکتے ہو: اب اگر تم تحریر پڑھ سکتے ہو، اور اس کی تشریح مجھے بتا سکتے ہو، تو تم سرخ لباس میں ملبوس ہو جاؤ گے، اور اپنی گردن میں سونے کی زنجیر بناؤ گے، اور بادشاہت کے تیسرے حکمران بنو گے۔ {تشریحات کریں: کالڈی، تشریح وغیرہ}\n17۔ پھر دانیال نے بادشاہ کے سامنے جواب دیا اور کہا، \"اپنے تحفے اپنے لیے رکھو، اور اپنا انعام کسی اور کو دے دو؛ پھر بھی میں بادشاہ کو تحریر پڑھوں گا، اور اسے اس کی تشریح بتاؤں گا۔ {انعامات: یا، فیس}\n18۔ اے بادشاہ، سب سے بلند خدا نے اپنے والد نبوکدنضر کو بادشاہت، عظمت، جلال اور عزت دی:\n19۔ اور جو عظمت اس نے اسے دی، اس کے لیے تمام لوگ، قومیں اور زبانیں اس کے سامنے کانپ اٹھیں اور خوفزدہ ہو گئیں: جنہیں وہ مارنا چاہتا تھا؛ اور جسے وہ زندہ رکھنا چاہتا تھا؛ اور جسے وہ مقرر کرنا چاہتا تھا؛ اور جسے وہ نیچا دکھانا چاہتا تھا۔\n20۔ لیکن جب اس کا دل بلند ہوا، اور اس کا ذہن غرور میں سخت ہو گیا، تو اسے اس کے بادشاہ کے تخت سے ہٹا دیا گیا، اور اس کی شان اس سے چھین لی گئی: {غرور میں: یا، فخر سے پیش آنے کے لیے} {معزول شدہ: کلدی، نیچے اتارنے کے لیے}\n21۔ اور اسے انسانوں کے بیٹوں سے نکال دیا گیا؛ اور اس کا دل جانوروں کی طرح بنا گیا، اور اس کا گھر جنگلی گدھوں کے ساتھ تھا: وہ اسے بیلوں کی طرح گھاس کھلاتے تھے، اور اس کا جسم آسمان کی اوس سے بھیگ گیا تھا؛ یہاں تک کہ اسے معلوم ہو گیا کہ سب سے اعلیٰ خدا انسانوں کی بادشاہی میں حکمرانی کرتا ہے، اور {کہ} وہ اس پر جسے چاہے مقرر کرتا ہے۔ {اس کا دل...: یا، اس نے اپنا دل برابر بنایا، وغیرہ}\n22۔ اور تو، اس کے بیٹے، اے بلشزار، نے اپنے دل کو عاجز نہیں کیا، حالانکہ تم یہ سب جانتے تھے؛\n23۔ لیکن آسمان کے رب کے خلاف خود کو اٹھا لیا ہے؛ اور انہوں نے اس کے گھر کے برتن تمہارے سامنے لائے ہیں، اور تم، تمہارے آقا، تمہاری بیویاں، اور تمہاری کنیزوں نے ان میں شراب پی ہے؛ اور تم نے چاندی اور سونا، پیتل، لوہا، لکڑی اور پتھر کے دیوتاؤں کی تعریف کی ہے، جو نہ دیکھتے ہیں، نہ سنتے ہیں، نہ جانتے ہیں؛ اور وہ خدا جس کے ہاتھ میں تمہاری سانس ہے، اور جس کے تمام راستے ہیں، تم نے جلال نہیں دیا:\n24۔ پھر ہاتھ کا وہ حصہ تھا جو اس نے بھیجا تھا؛ اور یہ تحریر لکھی گئی تھی۔\n25۔ اور یہ وہ تحریر ہے جو لکھی گئی تھی، مینے، مینے، ٹیکل، اپہارسن۔\n26. یہ {ہے} چیز کی تشریح: MENE؛ خدا نے تمہاری بادشاہی کو گنا ہے، اور اسے مکمل کیا ہے۔\n27۔ ٹیکل؛ تم ترازو میں تولے جاتے ہو، اور تم کمزور پائے جاتے ہو۔\n28۔ پیریس؛ تمہاری بادشاہت تقسیم ہو گئی ہے، اور میدوں اور فارسیوں کو دی گئی ہے۔\n29۔ پھر بلشصر نے حکم دیا، اور انہوں نے دانیال کو سرخ لباس پہنایا، اس کی گردن میں سونے کی زنجیر ڈالی، اور اس کے بارے میں اعلان کیا کہ وہ بادشاہت کا تیسرا حکمران ہوگا۔\n30۔ اسی رات بلشصر، کلدانیوں کا بادشاہ، مارا گیا۔\n31۔ اور داریوش میڈین نے بادشاہی سنبھالی، {جو تقریبا تیس اور دو سال کا تھا}۔ {ہونا...: چالڈی، وہ بطور بیٹا، وغیرہ} {اب: یا، اب}","1۔ داریوس کو یہ پسند آیا کہ وہ سلطنت پر ایک سو بیس شہزادے مقرر کرے، جو پورے سلطنت پر ہونے چاہئیں؛\n2۔ اور ان تین صدور پر؛ جس کا دانیال سب سے پہلے تھا: تاکہ شہزادے ان کے حساب کتاب کر سکیں، اور بادشاہ کو کوئی نقصان نہ پہنچے۔\n3۔ پھر یہ دانیال صدور اور شہزادوں پر فوقیت رکھتا تھا، کیونکہ اس میں ایک بہترین روح تھی؛ اور بادشاہ نے سوچا کہ اسے پورے سلطنت پر حکمرانی کرے۔\n4۔ پھر صدور اور شہزادوں نے بادشاہت کے حوالے سے دانیال کے خلاف موقع تلاش کرنے کی کوشش کی؛ لیکن انہیں کوئی موقع یا خامی نظر نہیں آئی؛ جتنا وہ وفادار تھا، اس میں کوئی غلطی یا خامی نہیں تھی۔\n5۔ پھر ان لوگوں نے کہا، \"ہمیں اس دانیال کے خلاف کوئی موقع نہیں ملے گا، جب تک کہ ہم اس کے خدا کے قانون کے بارے میں اس کے خلاف نہ پائیں۔\n6۔ پھر یہ صدور اور شہزادے بادشاہ کے سامنے جمع ہوئے اور اس سے کہا، بادشاہ داریوش، ہمیشہ زندہ رہو۔ {جمع...: یا، ہنگامہ خیز انداز میں آیا}\n7۔ سلطنت کے تمام صدور، گورنرز، شہزادے، مشیران اور کپتانوں نے مل کر مشاورت کی ہے کہ ایک شاہی قانون قائم کیا جائے، اور ایک پختہ حکم دیا جائے کہ جو بھی تیس دن کے لیے کسی خدا یا انسان سے درخواست مانگے، سوائے آپ کے، اے بادشاہ، اسے شیر کے غار میں پھینک دیا جائے گا۔ {فرمان: یا، روک تھام}\n8۔ اب، اے بادشاہ، فرمان قائم کرو اور تحریر پر دستخط کرو تاکہ یہ بدل نہ جائے، جیسا کہ میڈز اور فارسیوں کے قانون کے مطابق ہے، جو تبدیل نہیں ہوتا۔ {نہ بدلو: کلدی، نہ بدلو}\n9۔ اسی لیے بادشاہ داریوش نے تحریر اور فرمان پر دستخط کیے۔\n10۔ اب جب دانیال کو معلوم ہوا کہ تحریر پر دستخط ہو چکے ہیں، تو وہ اپنے گھر چلا گیا؛ اور جب اس کے کمرے کی کھڑکیاں یروشلم کی طرف کھلی تھیں، تو وہ دن میں تین بار گھٹنوں کے بل بیٹھتا، دعا کرتا اور اپنے خدا کے سامنے شکر ادا کرتا، جیسا کہ پہلے کرتا تھا۔\n11۔ پھر یہ لوگ جمع ہوئے، اور دانیال کو اپنے خدا کے سامنے دعا کرتے اور دعا کرتے پایا۔\n12۔ پھر وہ قریب آئے اور بادشاہ کے سامنے بادشاہ کے حکم کے بارے میں بات کی؛ کیا تم نے کوئی فرمان نہیں کیا کہ ہر وہ شخص جو تیس دن کے اندر کسی خدا یا انسان سے درخواست مانگے گا، سوائے تمہارے کے، اے بادشاہ، اسے شیر کے غار میں پھینک دیا جائے گا؟ بادشاہ نے جواب دیا اور کہا، یہ بات درست ہے، میدوں اور فارسیوں کے قانون کے مطابق، جو تبدیل نہیں ہوتا۔\n13۔ پھر انہوں نے جواب دیا اور بادشاہ کے سامنے کہا، کہ دانیال، جو یہوداہ کی قید کے بچوں میں سے ہے، نہ تمہیں دیکھتا ہے، اے بادشاہ، نہ اس فرمان کو جو تم نے دستخط کیا ہے، بلکہ دن میں تین بار درخواست کرتا ہے۔\n14۔ پھر بادشاہ نے جب یہ الفاظ سنے، تو خود سے سخت ناراض ہو گیا، اور اپنا دل دانیال پر رکھ دیا تاکہ اسے بچا سکے، اور سورج کے غروب ہونے تک اسے بچانے کے لیے محنت کی۔\n15۔ پھر یہ لوگ بادشاہ کے پاس جمع ہوئے اور بادشاہ سے کہا، اے بادشاہ، جان لو کہ میڈز اور فارسیوں کا قانون {ہے}، کہ بادشاہ جو حکم یا قانون مقرر کرتا ہے وہ تبدیل نہیں کیا جا سکتا۔\n16۔ پھر بادشاہ نے حکم دیا، اور انہوں نے دانیال کو لایا، اور اسے شیر کے غار میں پھینک دیا۔ {اب} بادشاہ نے دانیال سے کہا، تمہارا خدا جس کی تم مسلسل عبادت کرتے ہو، وہ تمہیں نجات دے گا۔\n17۔ اور ایک پتھر لایا گیا، اور غار کے منہ پر رکھا گیا؛ اور بادشاہ نے اسے اپنے دستخط اور اپنے لارڈز کے نشان سے مہر لگا دی؛ تاکہ ڈینیئل کے بارے میں مقصد تبدیل نہ ہو۔\n18۔ پھر بادشاہ اپنے محل گیا، اور رات روزہ گزاری: نہ ہی موسیقی کے ساز اس کے سامنے لائے گئے، اور اس کی نیند بھی ختم ہو گئی۔ {آلات...: یا، میز}\n19۔ پھر بادشاہ بہت صبح سویرے اٹھا اور جلدی سے شیروں کے غار کی طرف گیا۔\n20۔ اور جب وہ غار پر پہنچا، تو اس نے دانیال سے افسوس بھری آواز میں پکارا: {اور} بادشاہ نے دانیال سے کہا، اے دانیال، زندہ خدا کا بندہ، کیا تیرا خدا، جس کی تم مسلسل عبادت کرتے ہو، تمہیں شیروں سے بچا سکتا ہے؟\n21۔ پھر دانیال نے بادشاہ سے کہا، اے بادشاہ، ہمیشہ زندہ رہو۔\n22۔ میرے خدا نے اپنا فرشتہ بھیجا ہے، اور شیروں کے منہ بند کر دیے ہیں کہ انہوں نے مجھے نقصان نہ پہنچایا؛ کیونکہ اس کے سامنے مجھ میں معصومیت پائی گئی؛ اور تیرے سامنے، اے بادشاہ، میں نے کوئی نقصان نہیں پہنچایا۔\n23۔ پھر بادشاہ اس کے لیے بہت خوش ہوا اور حکم دیا کہ وہ دانیال کو غار سے باہر لے جائیں۔ لہٰذا دانیال کو غار سے باہر لے جایا گیا، اور اسے کوئی تکلیف نہیں پہنچی، کیونکہ وہ اپنے خدا پر ایمان رکھتا تھا۔\n24۔ اور بادشاہ نے حکم دیا، اور انہوں نے وہ آدمی لے آئے جنہوں نے دانیال پر الزام لگایا تھا، اور انہیں شیروں کے غار میں پھینک دیا، انہیں، ان کے بچے اور ان کی بیویاں؛ اور شیر ان پر قابو پا چکے تھے، اور ان کی تمام ہڈیاں ٹکڑے ٹکڑے کر دیتے یا کبھی وہ غار کے نیچے پہنچتے۔\n25۔ پھر بادشاہ داریوش نے زمین پر رہنے والے تمام لوگوں، قوموں اور زبانوں کو خط لکھا؛ آپ پر سلامتی ملے۔\n26. میں ایک فرمان دیتا ہوں کہ میری بادشاہی کی ہر سلطنت میں لوگ دانیال کے خدا کے سامنے کانپیں اور خوفزدہ ہوں: کیونکہ وہ زندہ خدا ہے، ہمیشہ کے لیے قائم ہے، اور اس کی بادشاہی وہ ہے جو کبھی ختم نہیں ہوگی، اور اس کی سلطنت آخر تک برابر رہے گی۔\n27۔ وہ نجات دیتا ہے اور نجات دیتا ہے، اور آسمان و زمین میں نشانیاں اور عجائبات کرتا ہے، جس نے دانیال کو شیروں کی طاقت سے نجات دی۔ {پاور: چالڈی، ہاتھ}\n28۔ یوں یہ دانیال داریوش کی حکومت اور سائرس فارسی کے دور میں خوشحال ہوا۔","1۔ بابل کے بادشاہ بلشصر کے پہلے سال میں دانیال نے اپنے بستر پر اپنے سر کا خواب اور خواب دیکھا: پھر اس نے خواب لکھا، {اور} معاملات کا خلاصہ بیان کیا۔ {تھا: چالڈی، آرا} {معاملات: یا، الفاظ}\n2۔ دانیال نے کہا کہ میں نے اپنی نظر میں رات کو دیکھا، اور دیکھو، آسمان کی چار ہوائیں عظیم سمندر پر چل رہی تھیں۔\n3۔ اور چار عظیم جانور سمندر سے نکلے، جو ایک دوسرے سے مختلف تھے۔\n4۔ پہلا {تھا} شیر کی طرح تھا، اور اس کے پر عقاب کے تھے: میں نے دیکھا جب تک کہ اس کے پر نکالے گئے، اور وہ زمین سے اٹھا ہوا، اور ایک انسان کی طرح پیروں پر کھڑا ہو گیا، اور ایک آدمی کا دل اس کے لیے دیا گیا۔ {اور یہ: یا، جس کے ساتھ ہے}\n5۔ اور دیکھو ایک اور جانور، دوسرا، جو ریچھ جیسا ہے، اور اس نے ایک طرف سے خود کو اٹھایا، اور اس کے منہ میں اس کے دانتوں کے درمیان تین پسلیاں تھیں: اور انہوں نے اسے کہا، اٹھو، بہت سا گوشت کھا لو۔ {اس نے اٹھایا...: یا، اس نے ایک ڈومینین اٹھایا}\n6۔ اس کے بعد میں نے ایک اور چیتے کی طرح دیکھا، جس کی پشت پر پرندوں کے چار پر تھے؛ اس جانور کے چار سر بھی تھے؛ اور اسے حکمرانی مل گئی۔\n7۔ اس کے بعد میں نے رات کے خوابوں میں چوتھا جانور دیکھا، جو خوفناک اور خوفناک تھا، اور بہت طاقتور تھا؛ اور اس کے بڑے لوہے کے دانت تھے: وہ ٹکڑوں میں کھا جاتا اور ٹوٹتا تھا، اور اپنے پیروں سے باقیات کو روند دیتا تھا: اور یہ تمام جانوروں سے مختلف تھا جو اس سے پہلے تھے؛ اور اس کے دس سینگ تھے۔\n8۔ میں نے سینگوں کو غور سے دیکھا، اور دیکھو، ان میں سے ایک اور چھوٹا سینگ نکلا، جس کے سامنے جڑوں سے نکالے گئے پہلے تین سینگ تھے: اور دیکھو، اس سینگ میں انسان کی آنکھوں کی طرح آنکھیں تھیں، اور ایک منہ جو بڑی باتیں کر رہا تھا۔\n9۔ میں نے دیکھا کہ تخت گر گئے، اور قدیم زمانے بیٹھا رہا، جس کا لباس برف کی طرح سفید تھا، اور اس کے سر کے بال خالص اون کی طرح تھے: اس کا تخت آگ کی طرح تھا، اور اس کے پہیے آگ کی طرح جل رہے تھے۔\n10۔ ایک آگ کی ندی نکلی اور اس کے سامنے سے نکلی: ہزاروں ہزاروں اس کی خدمت کرنے لگے، اور دس ہزار بار دس ہزار اس کے سامنے کھڑے ہوئے: فیصلہ مقرر کیا گیا، اور کتابیں کھل گئیں۔\n11۔ میں نے اس عظیم الفاظ کی آواز کی وجہ سے دیکھا جو سینگ نے کہے: میں نے دیکھا {حتی} جب تک کہ جانور مارا گیا، اس کا جسم تباہ نہ ہو گیا، اور اسے جلتی ہوئی آگ میں دے دیا گیا۔\n12۔ باقی جانوروں کے بارے میں، ان کی حکمرانی چھین لی گئی: پھر بھی ان کی زندگی ایک موسم اور وقت کے لیے طول دی گئی۔ {ان کی زندگی...: چالڈی، انہیں زندگی میں توسیع دی گئی}\n13۔ میں نے رات کے خوابوں میں دیکھا، اور دیکھو، {ایک} انسان کے بیٹے کی طرح آسمان کے بادلوں کے ساتھ آیا، اور قدیم زمانے کے پاس آیا، اور وہ اسے اس کے قریب لے آئے۔\n14۔ اور اسے حکمرانی، جلال اور ایک بادشاہی دی گئی، جس کی خدمت تمام قوم، قوموں اور زبانوں کو کرنی چاہیے: اس کی سلطنت ایک دائمی حکمرانی ہے، جو کبھی ختم نہیں ہوگی، اور اس کی بادشاہی جو کبھی تباہ نہیں ہوگی۔\n15. میں دانیال اپنی روح میں اپنے جسم کے درمیان غمگین تھا، اور میرے ذہن کے مناظر نے مجھے پریشان کیا۔ {جسم: چالڈی، میان}\n16۔ میں ان میں سے ایک کے قریب گیا جو وہاں کھڑا تھا، اور اس سے اس سب کی حقیقت پوچھی۔ تو اس نے مجھے بتایا، اور مجھے ان چیزوں کی تشریح سمجھائی۔\n17۔ یہ عظیم جانور، جو چار ہیں، چار بادشاہ ہیں، {جو} زمین سے جنم لیں گے۔\n18۔ لیکن سب سے بلند کے مقدس بادشاہی سنبھالیں گے، اور ہمیشہ کے لیے بادشاہی کے مالک رہیں گے۔ {زیادہ تر...: چالڈی، اونچے، یعنی چیزیں، یا جگہیں}\n19۔ تب میں چوتھے جانور کی سچائی جاننا چاہوں گا، جو باقی سب سے مختلف تھا، انتہائی خوفناک تھا، جس کے دانت لوہے کے تھے اور اس کے ناخن پیتل کے تھے؛ {جو} نے کھا لیا، ٹکڑوں میں ٹوٹا، اور اپنے پیروں سے باقیات کو روند ڈالا؛ {سے...: چالڈی، ان سب سے}\n20۔ اور ان دس سینگوں میں سے جو {تھے} اس کے سر میں، اور {دوسرا} جو نکلا، اور جس کے سامنے تین گرے؛ یہاں تک کہ وہ سینگ جس کی آنکھیں تھیں، اور منہ جو بہت بڑی باتیں کرتا تھا، جس کی شکل اپنے ساتھیوں سے زیادہ مضبوط تھی۔\n21۔ میں نے دیکھا، اور اسی سینگ نے مقدسین سے جنگ کی، اور ان پر غالب آ گیا؛\n22۔ یہاں تک کہ قدیم زمانے آئے، اور سب سے اعلیٰ کے مقدسین کو فیصلہ دیا گیا؛ اور وہ وقت آیا جب مقدسین نے بادشاہی حاصل کی۔\n23۔ یوں اس نے کہا، چوتھی درندہ زمین پر چوتھی بادشاہت ہوگی، جو تمام بادشاہتوں سے مختلف ہوگی، اور پوری زمین کو نگل جائے گی، اسے روند دے گی اور ٹکڑوں میں بکھیر دے گی۔\n24۔ اور اس سلطنت کے دس سینگ دس بادشاہ ہیں جو ابھریں گے: اور ان کے بعد دوسرا بادشاہ اٹھے گا؛ اور وہ پہلے سے مختلف ہوگا، اور تین بادشاہوں کو زیر کرے گا۔\n25۔ اور وہ اعلیٰ کے خلاف {عظیم} الفاظ کہے گا، اور سب سے بلند کے مقدسین کو تھکا دے گا، اور وقت اور قوانین بدلنے کا سوچے گا: اور وہ وقت اور وقت کی تقسیم تک اس کے ہاتھ میں دے دیے جائیں گے۔\n26۔ لیکن فیصلہ ہوگا، اور وہ اس کی حکمرانی چھین لیں گے، اسے ختم اور ختم کریں گے۔\n27۔ اور بادشاہی، حکمرانی، اور پورے آسمان کے نیچے بادشاہی کی عظمت، سب سے اعلیٰ کے مقدسین کے لوگوں کو دی جائے گی، جن کی بادشاہی ایک دائمی بادشاہی ہے، اور تمام سلطنتیں اس کی خدمت اور اطاعت کریں گی۔ {ڈومینینز: یا، حکمران}\n28۔ اب تک معاملہ ختم ہو چکا ہے۔ جہاں تک ڈینیئل کا تعلق ہے، میرے خیالات نے مجھے بہت پریشان کیا، اور میرا چہرہ بدل گیا: لیکن میں نے یہ بات دل میں رکھی۔","1۔ بادشاہ بلشصر کے بادشاہ کے تیسرے سال میں مجھے ایک خواب آیا، {یہاں تک کہ} کہ مجھے ڈینیئل، جو پہلی بار ظاہر ہوا تھا۔\n2۔ اور میں نے ایک خواب میں دیکھا؛ اور جب میں نے دیکھا کہ میں شوشان میں محل میں ہوں، جو ایلام کے صوبے میں ہے؛ اور میں نے ایک خواب میں دیکھا، اور میں الائی دریا کے کنارے تھا۔\n3۔ پھر میں نے اپنی آنکھیں اٹھائیں، اور دیکھا، اور دیکھو، دریا کے سامنے ایک مینڈھا کھڑا تھا جس کے {دو} سینگ تھے: اور {دو} سینگ {اونچے} تھے؛ لیکن ایک دوسرے سے اوپر تھا، اور اونچا آخر میں آیا۔ {دوسرا: عبرانی۔ دوسرا}\n4۔ میں نے مینڈھے کو مغرب، شمال اور جنوب کی طرف بڑھتے دیکھا؛ تاکہ کوئی جانور اس کے سامنے نہ کھڑا ہو سکے، اور نہ ہی کوئی ایسا تھا جو اس کے ہاتھ سے نجات دے سکے؛ لیکن اس نے اپنی مرضی کے مطابق کام کیا، اور عظیم بن گیا۔\n5۔ اور جب میں غور کر رہا تھا، دیکھو، ایک بکری مغرب سے پوری زمین کے چہرے پر آئی اور زمین کو چھو نہیں رہی تھی: اور بکری کی آنکھوں کے درمیان ایک نمایاں سینگ تھا۔ {چھوا...: یا، زمین میں کسی نے اسے چھوا نہیں} {ایک قابل ذکر...: عبرانی ایک ہارن آف سائٹ}\n6۔ اور وہ اس مینڈھے کے پاس آیا جس کے {دو} سینگ تھے، جسے میں نے دریا کے سامنے کھڑا دیکھا تھا، اور اپنی طاقت کے غصے میں اس کی طرف دوڑا۔\n7۔ اور میں نے اسے مینڈھے کے قریب آتے دیکھا، اور وہ رینڈھے کے قریب آ گیا، اور اس نے مینڈھے کو مارا اور اس کے دونوں سینگ توڑ دیے: اور مینڈھے میں اس کے سامنے کھڑے ہونے کی طاقت نہ تھی، لیکن اس نے اسے زمین پر گرا دیا اور اس پر قدم رکھا: اور کوئی بھی اس کے ہاتھ سے مینڈھے کو چھین نہ سکا۔\n8۔ اسی لیے بکری بہت بڑی ہو گئی: اور جب وہ مضبوط ہوئی تو اس کا بڑا سینگ ٹوٹ گیا؛ اور اس کے لیے چار نمایاں آسمان کی ہواؤں کی طرف نمودار ہوئے۔\n9۔ اور ان میں سے ایک سے ایک چھوٹا سا سینگ نکلا، جو بہت بڑا تھا، جنوب، مشرق کی طرف، اور خوشگوار زمین کی طرف۔\n10۔ اور یہ آسمان کی فوج تک بہت بڑا ہو گیا؛ اور اس نے لشکر اور ستاروں کے کچھ حصے زمین پر گرا دیے، اور ان پر قدم رکھا۔ {میزبان کو: یا، میزبان کے خلاف}\n11۔ ہاں، اس نے خود کو لشکر کے شہزادے تک بھی بڑھا دیا، اور اس کے ہاتھوں روزانہ کی قربانی چھین لی گئی، اور اس کے مقدس مقام کو گرا دیا گیا۔ {تو: یا، خلاف} {اس کے ذریعے: یا، اس سے}\n12۔ اور ایک لشکر کو روزمرہ قربانی کے خلاف دیا گیا، جو ظلم کی وجہ سے تھا، اور اس نے سچائی کو زمین پر گرا دیا؛ اور اس نے عمل کیا، اور ترقی کی۔ {ایک میزبان...: یا، میزبان روزانہ قربانی کی خلاف ورزی کے لیے دیا گیا}\n13۔ پھر میں نے ایک ولی کو بولتے سنا، اور دوسرے ولی نے اس {ولی} سے کہا جس نے کہا، روزانہ {قربانی} اور ویرانی کی خلاف ورزی کے بارے میں خواب کب تک رہے گا، تاکہ پناہ گاہ اور لشکر دونوں کو پاؤں تلے روندا جا سکے؟ {وہ...: یا، رازوں کی گنتی کرنے والا، یا، حیرت انگیز گننے والا: عبرانی۔ پالمونی} {کا...: یا، ویران بنانا}\n14۔ اور اس نے مجھ سے کہا، دو ہزار تین سو دن تک؛ پھر مقدس مقام کو پاک کیا جائے گا۔ {دن: عبرانی۔ شام کی صبح} {صاف شدہ: عبرانی۔ justified}\n15۔ اور یہ ہوا، جب میں، {حتیٰ کہ} میں دانیال ہوں، نے وہ خواب دیکھا اور اس کا مطلب تلاش کیا، تو دیکھو، وہ میرے سامنے ایک انسان کی شکل میں کھڑا تھا۔\n16۔ اور میں نے ایک آدمی کی آواز سنی {اولائی کے کنارے} کے درمیان، جس نے پکارا، اور کہا، جبرائیل، اس {آدمی} کو خواب کو سمجھنے کے لیے تیار کرو۔\n17۔ تو وہ اس جگہ کے قریب آیا جہاں میں کھڑا تھا، اور جب وہ آیا تو میں ڈر گیا، اور اپنے چہرے پر گر پڑا، لیکن اس نے مجھ سے کہا، اے انسان کے بیٹے، سمجھو، کیونکہ انجام کے وقت خواب ہوگا۔\n18۔ اب جب وہ مجھ سے بات کر رہا تھا، میں گہری نیند میں تھا اور میرا چہرہ زمین کی طرف تھا: لیکن اس نے مجھے چھوا اور مجھے سیدھا کر دیا۔ {سیٹ...: عبوری۔ مجھے اپنی جگہ پر کھڑا کر دیا}\n19۔ اور اس نے کہا، دیکھو، میں تمہیں بتاؤں گا کہ غصے کے آخری انجام میں کیا ہوگا: کیونکہ مقررہ وقت پر انجام {ہو گا}۔\n20۔ وہ مینڈھا جس کے {دو} سینگ ہیں {وہ مادی اور فارس کے بادشاہ ہیں}۔\n21. اور کھردرا بکری یونان کا بادشاہ ہے: اور عظیم سینگ جو اس کی آنکھوں کے درمیان ہے پہلا بادشاہ ہے۔\n22۔ اب جب کہ چار بادشاہتیں ٹوٹ گئیں، جبکہ چار نے اس کے لیے کھڑے ہوئے، چار بادشاہتیں قوم سے باہر آئیں گی، لیکن اس کی طاقت میں نہیں۔\n23۔ اور ان کی بادشاہت کے آخری دور میں، جب مجرموں کو مکمل طور پر دیکھا جائے گا، ایک بادشاہ جو سخت چہرے اور سمجھدار سیاہ جملوں کا حامل ہو، کھڑا ہوگا۔ {آر...: عبرانی مکمل ہو چکے ہیں}\n24۔ اور اس کی طاقت بہت طاقتور ہوگی، لیکن اپنی طاقت سے نہیں: اور وہ حیرت انگیز طریقے سے تباہ کرے گا، ترقی کرے گا، عمل کرے گا، اور طاقتور اور مقدس لوگوں کو تباہ کرے گا۔ {مقدس...: عبرانی۔ مقدس لوگوں کے لوگ}\n25۔ اور اپنی پالیسی کے ذریعے وہ اپنے ہاتھ میں ہنر کو فروغ دے گا؛ اور وہ اپنے دل میں خود کو بڑھائے گا، اور امن کے ذریعے بہت سے لوگوں کو تباہ کرے گا: وہ شہزادوں کے شہزادے کے خلاف بھی کھڑا ہوگا؛ لیکن وہ بغیر ہاتھ کے ٹوٹ جائے گا۔ {امن: یا، خوشحالی}\n26۔ اور شام اور صبح کا وہ خواب جو بتایا گیا {ہے} سچ ہے: لہٰذا تو اس خواب کو بند کر دو؛ کیونکہ یہ کئی دنوں تک رہے گا۔\n27۔ اور میں دانیال بے ہوش ہو گیا، اور کچھ دنوں میں بیمار رہا؛ بعد میں میں اٹھ کھڑا ہوا، اور بادشاہ کا کام کیا؛ اور میں اس منظر پر حیران رہ گیا، لیکن کوئی بھی اسے سمجھ نہ سکا۔","1۔ داریوش کے پہلے سال میں، اہاسیوروس کا بیٹا، جو میدوں کی نسل سے تھا، جسے کلدانیوں کی سلطنت کا بادشاہ بنایا گیا؛ {کون: یا، جس میں وہ}\n2۔ اپنی بادشاہت کے پہلے سال میں، اول دانیال نے کتابوں کے ذریعے ان سالوں کی تعداد سمجھی جن میں خداوند کا کلام یرمیاہ نبی تک پہنچا، کہ وہ یروشلم کی ویرانی میں ستر سال مکمل کرے گا۔\n3۔ اور میں اپنا چہرہ خداوند خدا کی طرف جھکتا ہوں، دعا اور دعاؤں کے ذریعے، روزہ، تھیلے کے کپڑے اور راکھ کے ذریعے دعا کرتا ہوں:\n4۔ اور میں نے خداوند میرے خدا سے دعا کی، اپنا اعتراف کیا، اور کہا، اے خداوند، عظیم اور خوفناک خدا، ان لوگوں کے لیے جو اس سے محبت کرتے ہیں، اور جو اس کے احکامات کی پاسداری کرتے ہیں، ان کے لیے عہد اور رحمت کو پورا کرتے ہوئے؛\n5۔ ہم نے گناہ کیا ہے، گناہ کیا ہے، بدکاری کی ہے، اور بغاوت کی ہے، یہاں تک کہ تمہارے احکامات اور فیصلوں سے انحراف کر کے:\n6۔ نہ ہی ہم نے تمہارے بندوں کو ان نبیوں کی بات سنی جو تیرے نام پر ہمارے بادشاہوں، ہمارے شہزادوں، اور ہمارے آباؤ اجداد اور زمین کے تمام لوگوں سے بات کرتے تھے۔\n7۔ اے خداوند، راستبازی {تیری} کی ہے، لیکن آج کی طرح ہمارے چہروں کی الجھن ہے؛ یہوداہ کے لوگوں کو، یروشلم کے باشندوں کو، اور تمام اسرائیل کو، جو قریب ہیں، اور دور ہیں، ان تمام ملکوں سے جہاں سے تم نے انہیں نکالا، ان کے گناہ کی وجہ سے جو انہوں نے تمہارے ساتھ کیے ہیں۔ {تعلق رکھتا ہے...: یا، تم یہاں ہو}\n8۔ اے خداوند، چہرے کی الجھن ہمارے لیے ہے، ہمارے بادشاہوں کی، ہمارے شہزادوں کی، اور ہمارے آباواجداد کی، کیونکہ ہم نے تیرے خلاف گناہ کیا ہے۔\n9۔ رحمت اور معافی خداوند کے پاس ہے، اگرچہ ہم نے اس کے خلاف بغاوت کی ہے؛\n10۔ نہ ہی ہم نے خداوند ہمارے خدا کی آواز کی اطاعت کی، تاکہ اس کے قوانین پر عمل کریں، جو اس نے اپنے بندوں، نبیوں کے ذریعے ہمارے سامنے رکھے۔\n11۔ ہاں، تمام اسرائیل نے تیری شریعت کی خلاف ورزی کی ہے، یہاں تک کہ چلے گئے، تاکہ وہ تیری آواز کی اطاعت نہ کریں؛ لہٰذا ہم پر لعنت نازل کی گئی ہے، اور وہ قسم جو موسیٰ کے شریعت میں لکھی گئی ہے، خدا کے بندے کی، کیونکہ ہم نے اس کے خلاف گناہ کیا ہے۔\n12۔ اور اس نے اپنے الفاظ کی تصدیق کی، جو اس نے ہمارے خلاف اور ہمارے ججوں کے خلاف کہے جنہوں نے ہمیں فیصلہ کیا، اور ہم پر ایک بڑی برائی لا کر دی: کیونکہ پورے آسمان کے نیچے وہ نہیں ہوا جو یروشلم پر ہوا۔\n13. جیسا کہ موسیٰ کے قانون میں لکھا ہے، یہ ساری برائی ہم پر آئی ہے: پھر بھی ہم نے خداوند اپنے خدا کے سامنے دعا نہیں کی تاکہ ہم اپنی گناہوں سے منہ موڑ سکیں اور تیری سچائی کو سمجھ سکیں۔ {بنا...: عبرانی ہم نے اس کے چہرے کو نہیں دیکھا، وغیرہ}\n14۔ اسی لیے خداوند نے برائی کو دیکھا، اور ہم پر لایا: کیونکہ خداوند ہمارا خدا اپنے تمام اعمال میں نیک ہے، کیونکہ ہم نے اس کی آواز نہیں مانی۔\n15۔ اور اب، اے خداوند ہمارے خدا، جس نے اپنے لوگوں کو مصر کی سرزمین سے طاقتور ہاتھ سے نکالا اور تمہیں آج کی طرح شہرت دلائی ہے؛ ہم نے گناہ کیا ہے، ہم نے برے کام کیے ہیں۔ {حاصل ہوا...: عبوری۔ تمہیں ایک نام بنایا}\n16۔ اے خداوند، تیری تمام راستبازی کے مطابق، میں تجھ سے التجا کرتا ہوں کہ تیری ناراضگی اور غصہ تمہارے شہر یروشلم، اپنے مقدس پہاڑ سے دور ہو جائے: کیونکہ ہمارے گناہوں اور ہمارے باپ اجداد کی گناہوں کی وجہ سے، یروشلم اور تمہارا لوگ ان سب کے لیے ملامت بن گئے ہیں جو ہمارے ارد گرد ہیں۔\n17۔ اب، اے ہمارے خدا، اپنے بندے کی دعا اور اس کی دعائیں سن، اور اپنے چہرے کو اپنے ویران مقدس مقام پر چمکاؤ، خداوند کی خاطر۔\n18۔ اے میرے خدا، اپنا کان جھکا اور سنو؛ اپنی آنکھیں کھولو، اور ہماری ویرانی اور اس شہر کو دیکھو جو تیرے نام سے پکارا جاتا ہے: کیونکہ ہم اپنی راستبازی کے لیے آپ کے سامنے اپنی دعائیں پیش نہیں کرتے، بلکہ تیری عظیم رحمتوں کے لیے۔ {جو کہ...: عبرانی جس پر تیرا نام پکارا جاتا ہے} {موجود: عبرانی۔ گرنے کی وجہ\n19۔ اے خداوند، سنو؛ اے خداوند، معاف فرما؛ اے خداوند، سنو اور عمل کرو؛ اے میرے خدا، اپنے لیے اپنی بھلائی کے لیے عاجزی نہ کرو: کیونکہ تیرے شہر اور تمہارے لوگ تیرے نام سے پکارا جاتے ہیں۔\n20. اور جب میں بول رہا تھا، دعا کر رہا تھا، اپنے گناہ اور اپنی قوم اسرائیل کے گناہ کا اعتراف کر رہا تھا، اور اپنے خدا کے مقدس پہاڑ کے لیے خداوند میرے خدا کے سامنے اپنی دعا پیش کر رہا تھا؛\n21۔ جی ہاں، جب میں دعا میں بول رہا تھا، حتیٰ کہ وہ آدمی جبرائیل، جسے میں نے ابتدا میں خواب میں تیزی سے اڑتے ہوئے دیکھا تھا، شام کی قربانی کے وقت مجھے چھوا۔ {تیزی سے: عبرانی۔ تھکن کے ساتھ، یا، فرار کے ساتھ}\n22۔ اور اس نے مجھے اطلاع دی، مجھ سے بات کی، اور کہا، اے دانیال، میں اب تمہیں مہارت اور سمجھ دینے آیا ہوں۔ {تو...: عبرانی تمہیں ماہر بنانے کے لیے}\n23۔ تمہاری دعاؤں کے آغاز میں حکم سامنے آیا، اور میں تمہیں دکھانے آیا ہوں؛ کیونکہ تم بہت محبوب ہو: لہٰذا معاملہ سمجھو، اور وژن پر غور کرو۔ {حکم: عبرانی۔ word} {بہت زیادہ...: عبرانی۔ خواہشات کا آدمی}\n24۔ ستر ہفتے مقرر کیے گئے ہیں کہ تیری قوم اور تمہارے مقدس شہر پر گناہ ختم ہو، گناہوں کا خاتمہ ہو، گناہوں کا خاتمہ کیا جائے، گناہوں کی صلح کی جا سکے، دائمی راستبازی لائی جائے، وژن اور نبوت کو مہر لگا دی جائے، اور سب سے پاک کو مسح کیا جائے۔ {اختتام: یا، روک تھام} {ایک بناؤ...: یا، سیل کر دو} {پیش گوئی: عبرانی۔ نبی}\n25۔ تو جان لو اور سمجھو، {کہ} یروشلم کی بحالی اور تعمیر کے حکم کے آغاز سے لے کر مسیحا تک شہزادہ سات ہفتے، تین سو اور دو ہفتے ہوگا: گلی دوبارہ بنائی جائے گی، اور دیوار، حتیٰ کہ مشکل وقتوں میں بھی۔ {بنایا جائے...: عبرانی واپس آؤ اور تعمیر ہو جاؤ} {دیوار: یا، توڑو، یا، کھودو} {مشکل: عبرانی۔ اسٹریٹ آف}\n26۔ اور تین سو دو ہفتے بعد مسیحا کاٹ دیا جائے گا، مگر اس کے لیے نہیں: اور آنے والے شہزادے کے لوگ شہر اور مقدس مقام کو تباہ کر دیں گے؛ اور اس کا اختتام سیلاب کے ساتھ ہوگا، اور جنگ کے اختتام تک ویرانی کا تعین کیا جاتا ہے۔ {لیکن...: یا، اور کچھ نہیں ملے گا} {ویرانیاں...: یا، اسے ویرانیوں سے کاٹ دیا جائے گا}\n27۔ اور وہ ایک ہفتے کے لیے بہت سے لوگوں سے عہد کی تصدیق کرے گا: اور ہفتے کے درمیان وہ قربانی اور قربانی کو روک دے گا، اور گناہوں کے پھیلاؤ کے لیے اسے ویران کر دے گا، یہاں تک کہ مکمل ہونے تک، اور جو طے شدہ ہے ویرانوں پر ڈالا جائے گا۔ {عہد نامہ: یا، ایک معاہدہ} {یا، ان خوفناک فوجوں کے لیے} {دی ڈیسلیٹ: یا، دی ڈیسویلیٹر}","1۔ فارس کے بادشاہ سائرس کے تیسرے سال میں دانیال کو ایک خبر ملی، جس کا نام بلتشصر تھا؛ اور وہ چیز {تھی} سچ تھی، لیکن مقررہ وقت {لمبا} تھا: اور وہ چیز کو سمجھتا تھا، اور وژن کو سمجھتا تھا۔ {لمبا: عبرانی زبردست}\n2. ان دنوں میں ڈینیئل تین مکمل ہفتے سوگ منا رہا تھا۔ {مکمل...: عببرانی۔ ہفتوں کے دن}\n3۔ میں نے کوئی خوشگوار روٹی نہیں کھائی، نہ گوشت آیا نہ شراب، نہ میں نے خود کو مسح کیا، یہاں تک کہ تین ہفتے مکمل ہو گئے۔ {خوشگوار...: عبرانی۔ خواہشات کی روٹی}\n4۔ اور پہلے مہینے کے چوتھے اور بیسویں دن، جب میں عظیم دریا کے کنارے تھا، جو {ہے} ہدیکیل؛\n5۔ پھر میں نے اپنی آنکھیں اٹھائیں، اور دیکھا، اور ایک آدمی کو دیکھا جو لینن میں ملبوس تھا، جس کی کمر اوپاز کے عمدہ سونے سے لپٹی ہوئی تھی: {a...: عبرانی۔ ایک آدمی}\n6۔ اس کا جسم بھی بیرل کی طرح تھا، اس کا چہرہ بجلی کی طرح تھا، اس کی آنکھیں آگ کے چراغوں کی طرح تھیں، اور اس کے بازو اور پاؤں چمکدار پیتل کی طرح رنگین تھے، اور اس کے الفاظ کی آواز ہجوم کی آواز کی طرح تھی۔\n7۔ اور میں نے صرف دانیال نے وہ خواب دیکھا: کیونکہ جو لوگ میرے ساتھ تھے وہ منظر نہیں دیکھے؛ لیکن ان پر ایک زبردست زلزلہ آیا، جس کی وجہ سے وہ چھپنے کے لیے بھاگ گئے۔\n8۔ اسی لیے میں اکیلا رہ گیا، اور میں نے یہ عظیم خواب دیکھا، اور میرے اندر کوئی طاقت باقی نہ رہی: کیونکہ میری خوبصورتی میرے اندر فساد میں بدل گئی تھی، اور میں کوئی طاقت نہ رکھ سکا۔ {خوبصورتی: یا، زور}\n9۔ پھر بھی میں نے اس کے الفاظ کی آواز سنی: اور جب میں نے اس کے الفاظ کی آواز سنی، تو میں گہری نیند میں تھا اپنے چہرے پر، اور میرا چہرہ زمین کی طرف مڑا۔\n10۔ اور دیکھو، ایک ہاتھ نے مجھے چھوا، جس نے مجھے گھٹنوں کے بل اور ہاتھوں کی ہتھیلیوں پر رکھ دیا۔ {سیٹ: عبرانی منتقل ہو گیا}\n11۔ اور اس نے مجھ سے کہا، اے دانیال، اے بہت محبوب آدمی، جو میں تم سے کہہ رہا ہوں اسے سمجھو اور سیدھے کھڑے ہو جاؤ: کیونکہ میں اب تیرے پاس بھیجا گیا ہوں۔ اور جب اس نے یہ لفظ مجھ سے کہا، میں کانپتا کھڑا ہو گیا۔ {بہت زیادہ...: عبرانی خواہشات کی} {سیدھا کھڑا: عبرانی۔ تمہارے مقام پر}\n12۔ پھر اس نے مجھ سے کہا، ڈینیئل، ڈرو مت، کیونکہ پہلے دن سے جب تم نے اپنے دل کو سمجھنے اور اپنے خدا کے سامنے خود کو سزا دینے کی کوشش کی، تمہارے الفاظ سنے گئے، اور میں تمہارے الفاظ کے لیے آیا ہوں۔\n13۔ لیکن سلطنت فارس کے شہزادے نے مجھے ایک اور بیس دن برداشت کیا: لیکن دیکھو، مائیکل، جو اہم شہزادوں میں سے ایک تھا، میری مدد کے لیے آیا؛ اور میں وہاں فارس کے بادشاہوں کے ساتھ رہا۔ {چیف: یا، پہلے}\n14۔ اب میں آیا ہوں تاکہ تمہیں سمجھا سکوں کہ تمہارے لوگوں کے ساتھ آخری دنوں میں کیا ہوگا: کیونکہ پھر بھی یہ خواب {بہ} دنوں تک ہے۔\n15۔ اور جب اس نے مجھ سے یہ الفاظ کہے، تو میں نے اپنا چہرہ زمین کی طرف کر لیا، اور میں گونگا ہو گیا۔\n16۔ اور دیکھو، {ایک} کی طرح جیسے انسانوں کے بیٹوں کی مثال میرے ہونٹوں کو چھو رہی ہو: پھر میں نے منہ کھولا، اور بولی، اور اس سے کہا جو میرے سامنے کھڑا تھا، اے میرے رب، اس خواب سے میرے غم مجھ پر منتقل ہو گئے ہیں، اور میں نے طاقت نہیں رکھی۔\n17. کیونکہ میرے آقا کا خادم اس سے کیسے بات کر سکتا ہے؟ جہاں تک میرا تعلق ہے، فورا میرے اندر کوئی طاقت باقی نہ رہی، نہ ہی میرے اندر سانس باقی رہی۔ {وہ...: یا، میرے آقا کا یہ خادم}\n18۔ پھر دوبارہ آیا اور مجھے {ایک} انسان کی طرح چھوا، اور اس نے مجھے مضبوط کیا،\n19۔ اور کہا، اے محبوب انسان، ڈر مت: سلامتی ہو، مضبوط رہو، ہاں، مضبوط رہو۔ اور جب اس نے مجھ سے بات کی، تو میں مضبوط ہوا اور کہا، میرے رب بولے؛ کیونکہ تو نے مجھے مضبوط کیا ہے۔\n20۔ پھر اس نے کہا، کیا تم جانتے ہو میں تمہارے پاس کیوں آیا ہوں؟ اور اب میں واپس جاؤں گا فارس کے شہزادے کے ساتھ لڑنے کے لیے: اور جب میں جاؤں گا، تو گریشیا کا شہزادہ آئے گا۔\n21. لیکن میں تمہیں وہ دکھاؤں گا جو سچائی کی کتاب میں درج ہے: اور {ان باتوں} میں میرے ساتھ کوئی نہیں ہے، سوائے مائیکل تمہارا شہزادہ۔ {ہولڈتھ: عبوری۔ خود کو مضبوط کرتا ہے}","1۔ اسی طرح میں نے داریوش دی میدی کے پہلے سال میں، {حتیٰ کہ} میں نے اسے مضبوط کرنے اور اس کی تصدیق کرنے کے لیے کھڑا ہوا۔\n2. اور اب میں تمہیں سچ دکھاؤں گا۔ دیکھو، فارس میں اب بھی تین بادشاہ کھڑے ہوں گے؛ اور چوتھا سب سے کہیں زیادہ امیر ہوگا: اور اپنی دولت سے وہ سب کو یونان کی سلطنت کے خلاف بھڑکائے گا۔\n3۔ اور ایک طاقتور بادشاہ کھڑا ہوگا، جو بڑی حکمرانی کے ساتھ حکومت کرے گا، اور اپنی مرضی کے مطابق کام کرے گا۔\n4۔ اور جب وہ کھڑا ہوگا، اس کی بادشاہی ٹوٹ جائے گی، اور آسمان کی چار ہواؤں کی طرف تقسیم ہو جائے گی؛ اور نہ اس کی اولاد کو، نہ اس کی سلطنت کے مطابق جس پر اس نے حکومت کی: کیونکہ اس کی بادشاہت چھین لی جائے گی، حتیٰ کہ ان کے علاوہ دوسروں کے لیے بھی۔\n5۔ اور جنوب کا بادشاہ مضبوط ہوگا، اور اپنے شہزادوں میں سے ایک؛ اور وہ اس پر مضبوط ہوگا، اور حکمرانی کرے گا؛ اس کی سلطنت {ہوگی} ایک عظیم حکمرانی ہوگی۔\n6۔ اور سالوں کے آخر میں وہ خود کو متحد کر لیں گے؛ کیونکہ جنوب کی بادشاہ کی بیٹی شمال کے بادشاہ کے پاس آ کر معاہدہ کرے گی: لیکن وہ بازو کی طاقت برقرار نہیں رکھے گی؛ نہ وہ کھڑا ہوگا، نہ اس کا بازو: لیکن وہ چھوڑ دی جائے گی، اور وہ جنہوں نے اسے لایا، اور وہ جس نے اسے جنم دیا، اور وہ جس نے {ان} وقتوں میں اسے مضبوط کیا۔ {شامل ہوں...: عببرانی۔ خود کو جوڑیں} {an...: عبرانی۔ حقوق} {جس نے پیدا کیا...: یا، جسے اس نے جنم دیا}\n7۔ لیکن اس کی جڑوں کی ایک شاخ سے {ایک} اپنی جاگیر میں کھڑا ہوگا، جو فوج کے ساتھ آئے گا، اور شمال کے بادشاہ کے قلعے میں داخل ہوگا، ان کے خلاف لڑے گا، اور غالب آئے گا: {میں...: یا، اس کی جگہ پر، یا عہدے پر}\n8۔ اور قیدیوں کو مصر میں ان کے دیوتاؤں، ان کے شہزادوں کے ساتھ، {اور} چاندی اور سونے کے قیمتی برتنوں کے ساتھ لے جائے گا؛ اور وہ شمال کے بادشاہ سے بھی زیادہ سال زندہ رہے گا۔ {ان کا قیمتی...: عبرانی۔ ان کی خواہش کے برتن}\n9۔ تو جنوب کا بادشاہ {اپنی} سلطنت میں آئے گا، اور اپنی سرزمین میں واپس جائے گا۔\n10۔ لیکن اس کے بیٹے مشتعل ہوں گے، اور بڑی فوجوں کو جمع کریں گے: اور {ایک} ضرور آئے گا، بہائے گا، اور گزرے گا: پھر وہ واپس آئے گا، اور اپنے قلعے میں بھی متحرک ہو جائے گا۔ {ہو گا...: یا، جنگ ہو گی} {واپس آؤ...: یا، دوبارہ ہلچل مچاؤ}\n11۔ اور جنوب کا بادشاہ چولر کے ساتھ حرکت کرے گا، اور اس کے ساتھ لڑے گا، یہاں تک کہ شمال کے بادشاہ کے ساتھ بھی، اور وہ بڑی تعداد میں لگے گا؛ لیکن ہجوم اس کے ہاتھ میں دے دیا جائے گا۔\n12۔ {اور} جب وہ ہجوم کو لے جائے گا، اس کا دل بلند ہو جائے گا؛ اور وہ {کئی} دس ہزار کو گرا دے گا: لیکن وہ اس سے مضبوط نہیں ہوگا۔\n13۔ کیونکہ شمال کا بادشاہ واپس آئے گا، اور پہلے سے زیادہ بڑی تعداد میں فوج لے کر آئے گا، اور یقینا کچھ سالوں بعد بڑی فوج اور دولت کے ساتھ آئے گا۔ {بعد...: عبرانی۔ زمانوں کے اختتام پر، حتیٰ کہ سالوں میں}\n14۔ اور ان دنوں میں بہت سے لوگ جنوب کے بادشاہ کے خلاف کھڑے ہوں گے: اور تمہارے لوگوں کے ڈاکو بھی وژن قائم کرنے کے لیے بلند ہوں گے؛ لیکن وہ گر جائیں گے۔ {ڈاکو: عبرانی۔ ڈاکوؤں کے بچے}\n15۔ تو شمال کا بادشاہ آئے گا، ایک پہاڑ بنائے گا، اور سب سے زیادہ باڑ والے شہر لے گا: اور جنوب کی فوج برداشت نہیں کرے گی، نہ اس کے منتخب لوگوں کو، اور نہ ہی کوئی طاقت برداشت کرے گی۔ {سب سے زیادہ...: عبرانی۔ گولہ بارود کا شہر} {اس کے...: عبرانی۔ اس کے انتخاب کے لوگ}\n16۔ لیکن جو اس کے خلاف آئے گا وہ اپنی مرضی کے مطابق کرے گا، اور کوئی اس کے سامنے کھڑا نہیں ہوگا: اور وہ اس شاندار زمین میں کھڑا ہوگا، جو اس کے ہاتھوں ختم ہو جائے گی۔ {شاندار...: یا، اچھا، وغیرہ: عبرانی۔ آرائشی زمین}\n17۔ وہ اپنی پوری بادشاہی کی طاقت اور اپنے ساتھ سیدھے لوگوں کے ساتھ داخل ہونے کے لیے اپنا چہرہ بھی کھڑا کرے گا؛ ایسا ہی کرے گا: اور وہ اسے عورتوں کی بیٹی دے گا، اسے خراب کر دے گا: لیکن وہ اس کے ساتھ کھڑی نہیں رہے گی، نہ ہی اس کے حق میں ہوگی۔ {سیدھا...: یا، بہت زیادہ سیدھا پن: یا، برابر حالات} {کرپٹنگ: عبریانی۔ کرپٹ کرنا}\n18۔ اس کے بعد وہ جزیروں کی طرف رخ کرے گا، اور کئی جزیروں کو لے جائے گا: لیکن ایک شہزادہ اپنی طرف سے دی گئی ملامت کو ختم کر دے گا؛ اپنی ملامت کے بغیر وہ اسے اپنے خلاف کر دے گا۔ {for...: عبرانی۔ اس کے لیے} {ملامت ...: عبرانی۔ اس کی ملامت\n19۔ پھر وہ اپنا چہرہ اپنی زمین کے قلعے کی طرف موڑے گا: لیکن وہ لڑکھڑا جائے گا اور گر جائے گا، اور اسے نہیں ملے گا۔\n20۔ پھر وہ اپنی جاگیر میں بادشاہی کی شان میں ٹیکس بڑھانے والا کھڑا ہوگا: لیکن چند دنوں میں وہ نہ غصے میں اور نہ جنگ میں تباہ ہو جائے گا۔ {اسٹیٹ: یا، جگہ} {a...: عبرانی ایسا جس سے ایک ایگزیکٹر گزر جائے} {غصہ: عبرانی۔ غصہ}\n21۔ اور اس کی جاگیر میں ایک بدکردار شخص کھڑا ہوگا، جسے بادشاہی کی عزت نہیں دی جائے گی، بلکہ وہ امن سے آئے گا، اور خوشامد کے ذریعے بادشاہی حاصل کرے گا۔ {اسٹیٹ: یا، جگہ}\n22۔ اور سیلاب کے بازوؤں سے وہ اس کے سامنے سے بہہ جائیں گے، اور ٹوٹ جائیں گے؛ ہاں، عہد کا شہزادہ بھی۔\n23۔ اور جب اس کے ساتھ اتحاد ہو جائے گا تو وہ دھوکہ دہی کرے گا: کیونکہ وہ اوپر آئے گا، اور چھوٹے لوگوں کے ساتھ مضبوط ہو جائے گا۔\n24۔ وہ صوبے کے سب سے موٹے مقامات پر بھی امن سے داخل ہوگا؛ اور وہ وہ کرے گا جو اس کے باپ اجداد نے نہیں کیا، اور نہ ہی اس کے باپ دادا نے؛ وہ ان میں شکار، لوٹ مار اور دولت بکھیر دے گا: {ہاں}، اور وہ اپنے سازشوں کو مضبوط قلعوں کے خلاف پیش گوئی کرے گا، چاہے کچھ وقت کے لیے ہی کیوں نہ ہو۔ {پرامن طریقے سے...: یا، پرامن اور موٹے ماحول میں، وغیرہ} {پیش گوئی...: عبرانی۔ اس کے خیالات سوچیں}\n25۔ اور وہ اپنی طاقت اور حوصلے کو جنوب کے بادشاہ کے خلاف ایک بڑی فوج کے ساتھ متحرک کرے گا؛ اور جنوب کا بادشاہ ایک بہت بڑی اور طاقتور فوج کے ساتھ لڑائی کے لیے تیار کیا جائے گا؛ لیکن وہ کھڑا نہیں ہوگا: کیونکہ وہ اس کے خلاف سازشیں پیش گوئی کریں گے۔\n26۔ ہاں، جو اس کے گوشت کا حصہ کھاتے ہیں وہ اسے تباہ کر دیں گے، اور اس کی فوج بھر جائے گی: اور بہت سے مارے گئے ہوں گے۔\n27۔ اور دونوں بادشاہوں کے دل شرارت کے لیے ہوں گے، اور وہ ایک ہی میز پر جھوٹ بولیں گے؛ لیکن یہ کامیاب نہیں ہوگا: کیونکہ پھر بھی انجام مقررہ وقت پر ہوگا۔ {دل: عبرانی۔ ان کے دل}\n28۔ پھر وہ اپنی زمین میں دولت کے ساتھ واپس آئے گا؛ اور اس کا دل مقدس عہد کے خلاف ہوگا؛ اور وہ {کارنامے} کرے گا، اور اپنی سرزمین واپس جائے گا۔\n29۔ مقررہ وقت پر وہ واپس آئے گا اور جنوب کی طرف آئے گا؛ لیکن یہ پہلے والے یا دوسرے جیسا نہیں ہوگا۔\n30۔ کیونکہ چتیم کے جہاز اس کے خلاف آئیں گے: اس لیے وہ غمگین ہوگا، واپس آئے گا، اور مقدس عہد پر غصہ کرے گا: ایسا ہی کرے گا؛ وہ واپس بھی آئے گا، اور ان لوگوں کے ساتھ معلومات رکھے گا جو مقدس عہد کو ترک کرتے ہیں۔\n31۔ اور اس کے ہتھیار کھڑے ہوں گے، اور وہ طاقت کے مقدس مقام کو آلودہ کریں گے، روزانہ کی قربانی چھین لیں گے، اور وہ اس مکروہ کو زمین پر رکھیں گے جو ویران کر دیتا ہے۔ {maketh...: یا، حیران کرتا ہے}\n32۔ اور جو لوگ عہد کے خلاف برے کام کریں گے، وہ چاپلوسی سے بگاڑ دیں گے: لیکن جو لوگ اپنے خدا کو جانتے ہیں وہ مضبوط ہوں گے اور {کارنامہ} کریں گے۔ {کرپٹ: یا، دھوکہ دہی کی وجہ}\n33۔ اور جو لوگ لوگوں میں سمجھدار ہیں وہ بہت سے لوگوں کو سکھائیں گے: پھر بھی وہ تلوار، آگ، قید اور مال غنیمت سے {کئی} دنوں تک مارے جائیں گے۔\n34۔ اب جب وہ گریں گے، تو تھوڑی مدد کے ساتھ انہیں قبول کیا جائے گا: لیکن بہت سے خوشامد کے ساتھ ان سے چمٹ جائیں گے۔\n35۔ اور ان میں سے کچھ سمجھدار گر جائیں گے، انہیں آزمائیں گے، صاف کریں گے، اور {ان} کو سفید کریں گے، {حتیٰ کہ} انجام کے وقت تک: کیونکہ {یہ ابھی مقررہ وقت کے لیے ہے}۔ {کوشش کریں: یا، ان کے ذریعے کوشش کریں}\n36۔ اور بادشاہ اپنی مرضی کے مطابق کرے گا؛ اور وہ خود کو بلند کرے گا، ہر خدا سے بلند ہوگا، اور دیوتاؤں کے خدا کے خلاف حیرت انگیز باتیں کرے گا، اور اس وقت تک کامیاب ہوگا جب تک غصہ پورا نہ ہو جائے: کیونکہ جو طے ہو وہ ہوگا۔\n37۔ نہ وہ اپنے باپ اجداد کے خدا کو سمجھے گا، نہ عورتوں کی خواہش کو، نہ کسی خدا کو دیکھے گا، کیونکہ وہ خود کو سب سے بلند کرے گا۔\n38۔ لیکن اپنی جائیداد میں وہ طاقتوں کے خدا کی عزت کرے گا: اور جس خدا کو اس کے باپ و اجداد نہیں جانتے تھے، وہ سونے، چاندی، قیمتی پتھروں اور خوبصورت چیزوں سے عزت کرے گا۔ {میں...: یا، جہاں تک قادر مطلق خدا کا تعلق ہے، اپنی نشست پر وہ عزت کرے گا، ہاں، وہ ایک خدا کی عزت کرے گا، جسے وغیرہ} {اسٹیٹ: یا، اسٹیڈ} {فورسز: یا، گولہ بارود: عبرانی۔ معزیم، یا خدا کے محافظ} {خوشگوار: عبرانی۔ مطلوبہ چیزیں}\n39۔ وہ سب سے مضبوط قلعوں میں ایک اجنبی خدا کے ساتھ ایسا کرے گا، جسے وہ تسلیم کرے گا {اور} جلال میں اضافہ کرے گا: اور وہ انہیں بہت سے لوگوں پر حکمرانی کرنے پر مجبور کرے گا، اور زمین کو منافع کے لیے تقسیم کرے گا۔ {زیادہ تر...: عبرانی۔ گولہ بارود کے قلعے} {gain: Heb. ایک قیمت}\n40۔ اور اختتام کے وقت جنوب کا بادشاہ اس پر حملہ کرے گا: اور شمال کا بادشاہ اس کے خلاف ایک طوفان کی طرح آئے گا، رتھوں کے ساتھ، گھڑ سواروں کے ساتھ، اور بہت سے جہازوں کے ساتھ؛ اور وہ ملکوں میں داخل ہوگا، اور بھر جائے گا اور گزر جائے گا۔\n41۔ وہ بھی شاندار زمین میں داخل ہوگا، اور بہت سے {ملک} تباہ ہو جائیں گے: لیکن یہ اس کے ہاتھ سے نکل جائیں گے، حتیٰ کہ ایڈوم، موآب، اور آمون کے بچوں کے سردار بھی۔ {شاندار...: یا، اچھا، وغیرہ: عبرانی۔ خوشی کی سرزمین، یا، زیور}\n42۔ وہ اپنے ہاتھ کو بھی ملکوں پر بڑھائے گا: اور مصر کی سرزمین فرار نہیں ہو سکے گی۔ {کھینچ...: عبوری۔ بھیجیں}\n43. لیکن وہ سونے اور چاندی کے خزانے اور مصر کی تمام قیمتی چیزوں پر قابو رکھے گا: اور لیبیا اور ایتھوپیا اس کے قدموں پر ہوں گے۔\n44۔ لیکن مشرق اور شمال سے آنے والی خبریں اسے پریشان کریں گی: اس لیے وہ بڑی شدت سے تباہی اور بے شمار لوگوں کو مکمل طور پر ختم کرنے کے لیے نکلے گا۔\n45۔ اور وہ اپنے محل کے خیمے سمندروں کے درمیان مقدس پہاڑ میں لگائے گا؛ پھر بھی وہ اپنی موت کو پہنچے گا، اور کوئی اس کی مدد نہیں کرے گا۔ {شاندار...: یا، اچھا، وغیرہ: عبرانی۔ پاکیزگی کی خوشی کا پہاڑ}","1۔ اور اس وقت مائیکل کھڑا ہوگا، وہ عظیم شہزادہ جو تمہارے قوم کے بچوں کے لیے کھڑا ہے: اور ایک مصیبت کا وقت آئے گا، جو اس وقت سے کبھی نہیں آیا: اور اس وقت تمہارے لوگ آزاد ہوں گے، ہر وہ جو کتاب میں لکھا ہوگا۔\n2۔ اور ان میں سے بہت سے جو زمین کی مٹی میں سوتے ہیں جاگ جائیں گے، کچھ ہمیشہ کی زندگی کے لیے، اور کچھ ہمیشہ کی حقارت کے لیے۔\n3۔ اور جو دانا ہیں وہ آسمان کی روشنی کی طرح چمکیں گے؛ اور وہ جو بہت سے لوگوں کو راستبازی کی طرف ستاروں کی طرح ہمیشہ ہمیشہ کے لیے بدل دیتے ہیں۔ {وائز: یا، اساتذہ}\n4. لیکن تو، اے دانیال، الفاظ بند کرو اور کتاب کو مہر لگا دو، {حتیٰ کہ} انجام کے وقت تک: بہت سے لوگ ادھر ادھر دوڑیں گے، اور علم میں اضافہ ہوگا۔\n5۔ پھر میں نے دانیال نے دیکھا، اور دیکھو، وہاں دو اور کھڑے تھے، ایک دریا کے کنارے کے اس طرف، اور دوسرا دریا کے اس طرف۔ {بینک: عبوری۔ lip} {بینک: عبوری۔ لپ}\n6۔ اور {ایک} نے اس آدمی سے کہا جو کپڑے میں ملبوس تھا، جو دریا کے پانیوں پر تھا، ان عجائبات کے اختتام تک کتنا وقت لگے گا؟ {اوپر...: یا، اوپر سے}\n7۔ اور میں نے اس آدمی کو سنا جو کپڑے میں ملبوس تھا، جو دریا کے پانیوں پر تھا، جب اس نے اپنا دایاں اور بایاں ہاتھ آسمان کی طرف اٹھایا، اور اس کی قسم کھائی جو ہمیشہ زندہ رہتا ہے کہ یہ کچھ وقت، ڈیڑھ وقت تک ہوگا؛ اور جب وہ مقدس لوگوں کی طاقت کو منتشر کرنے میں کامیاب ہو جائے گا، تو یہ سب {کام} ختم ہو جائے گا۔ {ایک وقت...: یا، حصہ}\n8۔ اور میں نے سنا، لیکن سمجھ نہیں پایا: پھر میں نے کہا، اے میرے رب، ان {چیزوں} کا انجام کیا ہوگا؟\n9۔ اور اس نے کہا، اپنی راہ چلو، دانیال: کیونکہ الفاظ بند اور مہر بند ہیں جب تک کہ آخر نہ آئے۔\n10۔ بہت سے پاک کیے جائیں گے، سفید ہوں گے، اور آزمائے جائیں گے؛ لیکن بدکار برے عمل کریں گے: اور کوئی بھی بدکار نہیں سمجھے گا؛ لیکن دانا سمجھ جائیں گے۔\n11۔ اور جب {جو} روزانہ {قربان} لے جایا جائے گا، اور وہ مکروہ جو ویران کرے گا، {ہزار دو سو نوے دن ہوں گے}۔ {دی ابومینیشن ہے: عبرانی۔ اس مکروہ چیز کو قائم کرنے کے لیے} {maketh...: or, astonisheth}\n12۔ مبارک ہے وہ جو انتظار کرتا ہے، اور ہزار تین سو پانچ تیس دن تک آتا ہے۔\n13۔ لیکن تم اپنے راستے پر جاؤ یہاں تک کہ آخر میں {بنو}: کیونکہ تم آرام کرو گے، اور قیامت میں اپنی قسمت میں کھڑے رہو گے۔ {کیونکہ تم: یا، اور تو، وغیرہ}"];
